import React, { useEffect, useState } from 'react';
import { Vehicle, VehicleStatus } from '../types';

interface VehicleCardProps {
  vehicle: Vehicle;
  onClick: (vehicle: Vehicle) => void;
}

export const VehicleCard: React.FC<VehicleCardProps> = ({ vehicle, onClick }) => {
  const [timeLeft, setTimeLeft] = useState<string>('');

  useEffect(() => {
    const calculateTimeLeft = () => {
      const now = Date.now();
      const difference = vehicle.endTime - now;

      if (difference <= 0) {
        return 'Ended';
      }

      const hours = Math.floor((difference / (1000 * 60 * 60)));
      const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((difference % (1000 * 60)) / 1000);

      return `${hours}h ${minutes}m ${seconds}s`;
    };

    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);

    setTimeLeft(calculateTimeLeft());

    return () => clearInterval(timer);
  }, [vehicle.endTime]);

  const isLive = vehicle.status === VehicleStatus.LIVE;

  return (
    <div 
      className="bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow border border-gray-200 overflow-hidden flex flex-col cursor-pointer h-full"
      onClick={() => onClick(vehicle)}
    >
      <div className="relative h-48 w-full bg-gray-200">
        <img 
          src={`https://picsum.photos/id/${vehicle.imageSeed}/400/300`} 
          alt={`${vehicle.year} ${vehicle.make}`} 
          className="w-full h-full object-cover"
        />
        <div className="absolute top-2 left-2">
           <span className={`px-2 py-1 text-xs font-bold uppercase rounded-sm text-white ${isLive ? 'bg-red-600 animate-pulse' : 'bg-blue-600'}`}>
             {vehicle.status}
           </span>
        </div>
        <div className="absolute bottom-2 right-2 bg-black bg-opacity-70 text-white text-xs px-2 py-1 rounded">
          {vehicle.odometer.toLocaleString()} mi
        </div>
      </div>

      <div className="p-4 flex-1 flex flex-col">
        <h3 className="text-lg font-bold text-gray-900 leading-tight mb-1 hover:text-red-700 hover:underline">
          {vehicle.year} {vehicle.make} {vehicle.model}
        </h3>
        <p className="text-xs text-gray-500 mb-3">VIN: {vehicle.vin}</p>

        <div className="grid grid-cols-2 gap-y-2 gap-x-4 text-sm mb-4">
          <div>
            <span className="block text-gray-500 text-xs">Primary Damage</span>
            <span className="font-medium text-gray-800">{vehicle.primaryDamage}</span>
          </div>
          <div>
            <span className="block text-gray-500 text-xs">Est. Value</span>
            <span className="font-medium text-gray-800">${vehicle.estRetailValue.toLocaleString()}</span>
          </div>
          <div>
            <span className="block text-gray-500 text-xs">Location</span>
            <span className="font-medium text-gray-800 truncate">{vehicle.location}</span>
          </div>
          <div>
            <span className="block text-gray-500 text-xs">Has Keys</span>
            <span className={`font-medium ${vehicle.hasKeys ? 'text-green-600' : 'text-red-600'}`}>
              {vehicle.hasKeys ? 'Yes' : 'No'}
            </span>
          </div>
        </div>

        <div className="mt-auto border-t pt-3">
          <div className="flex justify-between items-end">
            <div>
              <span className="block text-gray-500 text-xs uppercase tracking-wide">Current Bid</span>
              <span className="text-xl font-bold text-gray-900">${vehicle.currentBid.toLocaleString()}</span>
            </div>
            <div className="text-right">
              <span className="block text-gray-500 text-xs">Time Remaining</span>
              <span className={`font-mono font-medium ${isLive ? 'text-red-600' : 'text-gray-700'}`}>
                {timeLeft}
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Vehicle } from '../types';
import { generateVehicleAnalysis } from '../services/geminiService';

interface VehicleDetailProps {
  vehicle: Vehicle;
  onBack: () => void;
  onPlaceBid: (amount: number) => void;
}

export const VehicleDetail: React.FC<VehicleDetailProps> = ({ vehicle, onBack, onPlaceBid }) => {
  const [bidAmount, setBidAmount] = useState<number>(vehicle.currentBid + 100);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isLoadingAnalysis, setIsLoadingLoadingAnalysis] = useState(false);
  const [mainImage, setMainImage] = useState(`https://picsum.photos/id/${vehicle.imageSeed}/800/600`);

  const handleGenerateAnalysis = async () => {
    setIsLoadingLoadingAnalysis(true);
    const result = await generateVehicleAnalysis(vehicle);
    setAnalysis(result);
    setIsLoadingLoadingAnalysis(false);
  };

  const handleBidSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bidAmount > vehicle.currentBid) {
      onPlaceBid(bidAmount);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Breadcrumb / Back */}
      <button onClick={onBack} className="flex items-center text-red-700 hover:text-red-900 mb-6 font-medium text-sm">
        ← Back to Search Results
      </button>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Images & Details */}
        <div className="lg:col-span-2 space-y-6">

          {/* Main Gallery */}
          <div className="bg-white p-1 rounded-lg shadow border border-gray-200">
            <div className="h-96 w-full bg-gray-100 rounded overflow-hidden">
               <img src={mainImage} className="w-full h-full object-cover" alt="Main View" />
            </div>
            <div className="flex gap-2 mt-2 overflow-x-auto p-2">
               {[0, 1, 2, 3].map((i) => (
                 <img 
                   key={i}
                   src={`https://picsum.photos/id/${vehicle.imageSeed + i}/200/150`}
                   className="h-20 w-32 object-cover cursor-pointer hover:opacity-80 rounded border border-gray-300"
                   onClick={() => setMainImage(`https://picsum.photos/id/${vehicle.imageSeed + i}/800/600`)}
                   alt={`Thumbnail ${i}`}
                 />
               ))}
            </div>
          </div>

          {/* Vehicle Information */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
            <div className="bg-gray-50 px-6 py-4 border-b border-gray-200">
              <h2 className="text-lg font-bold text-gray-900">Vehicle Specifications</h2>
            </div>
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4 text-sm">
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">VIN</span>
                <span className="font-mono text-gray-900">{vehicle.vin}</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Odometer</span>
                <span className="font-medium text-gray-900">{vehicle.odometer.toLocaleString()} mi</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Primary Damage</span>
                <span className="font-bold text-red-600">{vehicle.primaryDamage}</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Secondary Damage</span>
                <span className="font-medium text-gray-900">{vehicle.secondaryDamage || 'N/A'}</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Engine</span>
                <span className="font-medium text-gray-900">{vehicle.engine}</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Drive</span>
                <span className="font-medium text-gray-900">{vehicle.drive}</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Transmission</span>
                <span className="font-medium text-gray-900">{vehicle.transmission}</span>
              </div>
              <div className="flex justify-between border-b border-gray-100 pb-2">
                <span className="text-gray-500">Keys Present</span>
                <span className={`font-bold ${vehicle.hasKeys ? 'text-green-600' : 'text-red-600'}`}>
                  {vehicle.hasKeys ? 'Yes' : 'No'}
                </span>
              </div>
            </div>
          </div>

          {/* AI Analysis Section */}
          <div className="bg-gradient-to-br from-indigo-50 to-white rounded-lg shadow-sm border border-indigo-100 overflow-hidden">
             <div className="px-6 py-4 border-b border-indigo-100 flex justify-between items-center">
                <div className="flex items-center gap-2">
                  <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                  <h2 className="text-lg font-bold text-indigo-900">AI Damage & Risk Insight</h2>
                </div>
                {!analysis && (
                  <button 
                    onClick={handleGenerateAnalysis}
                    disabled={isLoadingLoadingAnalysis}
                    className="text-xs bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-1.5 rounded-full transition-colors disabled:opacity-50"
                  >
                    {isLoadingLoadingAnalysis ? 'Analyzing...' : 'Generate Report'}
                  </button>
                )}
             </div>
             <div className="p-6">
                {!analysis && !isLoadingLoadingAnalysis && (
                  <p className="text-gray-500 text-sm italic">
                    Click "Generate Report" to get a detailed AI assessment of the repair complexity and potential hidden damages based on the vehicle data.
                  </p>
                )}
                {isLoadingLoadingAnalysis && (
                  <div className="animate-pulse space-y-3">
                    <div className="h-4 bg-indigo-200 rounded w-3/4"></div>
                    <div className="h-4 bg-indigo-200 rounded w-full"></div>
                    <div className="h-4 bg-indigo-200 rounded w-5/6"></div>
                  </div>
                )}
                {analysis && (
                   <div className="prose prose-sm prose-indigo text-gray-700 max-w-none">
                     <div dangerouslySetInnerHTML={{ __html: analysis.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br />') }} />
                   </div>
                )}
             </div>
          </div>
        </div>

        {/* Right Column: Bidding Interface */}
        <div className="space-y-6">
           <div className="bg-white p-6 rounded-lg shadow-md border-t-4 border-red-600 sticky top-24">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">
                {vehicle.year} {vehicle.make} {vehicle.model}
              </h1>
              <div className="flex items-center gap-2 text-sm text-gray-500 mb-6">
                <span className="bg-gray-100 px-2 py-1 rounded text-xs border border-gray-300">Run & Drive</span>
                <span>Lot #: {vehicle.id}</span>
                <span>{vehicle.location}</span>
              </div>

              <div className="bg-gray-50 p-4 rounded-lg mb-6 border border-gray-200">
                 <div className="flex justify-between items-center mb-1">
                   <span className="text-sm font-medium text-gray-500">Current Bid</span>
                   <span className="text-3xl font-bold text-gray-900">${vehicle.currentBid.toLocaleString()}</span>
                 </div>
                 {vehicle.buyNowPrice && (
                    <div className="flex justify-between items-center text-sm">
                      <span className="text-gray-500">Buy It Now</span>
                      <span className="font-semibold text-blue-700 cursor-pointer hover:underline">${vehicle.buyNowPrice.toLocaleString()}</span>
                    </div>
                 )}
              </div>

              <form onSubmit={handleBidSubmit} className="space-y-4">
                 <div>
                   <label className="block text-sm font-medium text-gray-700 mb-1">Your Max Bid</label>
                   <div className="relative">
                     <span className="absolute left-3 top-2.5 text-gray-500">$</span>
                     <input 
                        type="number"
                        value={bidAmount}
                        onChange={(e) => setBidAmount(parseInt(e.target.value) || 0)}
                        min={vehicle.currentBid + 50}
                        step={50}
                        className="w-full pl-7 pr-4 py-2 border border-gray-300 rounded focus:ring-2 focus:ring-red-500 focus:border-red-500 outline-none text-lg font-medium"
                     />
                   </div>
                   <p className="text-xs text-gray-500 mt-1">Minimum bid increment: $50</p>
                 </div>

                 <button 
                   type="submit"
                   className="w-full bg-red-600 text-white font-bold py-3 rounded hover:bg-red-700 transition-colors shadow-sm text-lg"
                 >
                   Place Bid
                 </button>
                 <button 
                   type="button"
                   className="w-full bg-white text-gray-700 font-medium py-2 rounded border border-gray-300 hover:bg-gray-50 transition-colors"
                 >
                   Add to Watchlist
                 </button>
              </form>

              <div className="mt-6 pt-6 border-t border-gray-200">
                 <h4 className="font-bold text-gray-900 text-sm mb-3">Sale Information</h4>
                 <div className="space-y-2 text-sm">
                   <div className="flex justify-between">
                     <span className="text-gray-500">Sale Date:</span>
                     <span className="text-gray-900">Today</span>
                   </div>
                   <div className="flex justify-between">
                     <span className="text-gray-500">Time Left:</span>
                     <span className="text-red-600 font-medium">Live Auction</span>
                   </div>
                   <div className="flex justify-between">
                     <span className="text-gray-500">Lane/Grid:</span>
                     <span className="text-gray-900">A / 104</span>
                   </div>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { Vehicle } from './types';
import { MOCK_VEHICLES } from './constants';

type ViewState = 'home' | 'detail' | 'dashboard';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string>('all');

  // Handle navigation
  const navigate = (view: ViewState) => {
    setCurrentView(view);
    window.scrollTo(0, 0);
  };

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    // Simulate placing a bid
    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { ...v, currentBid: amount } : v
    );
    setVehicles(updatedVehicles);

    // Update selected vehicle reference
    setSelectedVehicle({ ...selectedVehicle, currentBid: amount });

    alert(`Bid of $${amount.toLocaleString()} placed successfully!`);
  };

  // Filter Logic
  const filteredVehicles = vehicles.filter(v => {
    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    if (filterType === 'all') return true;
    if (filterType === 'buynow') return v.buyNowPrice !== undefined;
    if (filterType === 'suv') return v.drive === 'AWD' || v.drive === '4WD'; // Rough approximation

    return true;
  });

  return (
    <div className="min-h-screen bg-gray-100 font-sans text-gray-900">
      <Navbar onNavigate={(page) => navigate(page as ViewState)} activePage={currentView} />

      {/* Main Content Area */}
      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

            {/* Search & Filter Bar */}
            <div className="bg-white p-4 rounded-lg shadow-sm mb-6 flex flex-col md:flex-row gap-4 items-center justify-between">
              <div className="flex-1 w-full md:w-auto">
                <input 
                  type="text" 
                  placeholder="Quick Search: 2023 Tesla, Damage Type, VIN..." 
                  className="w-full border border-gray-300 rounded px-4 py-2 focus:ring-2 focus:ring-red-500 focus:border-red-500 outline-none"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
                <button 
                  onClick={() => setFilterType('all')}
                  className={`px-4 py-2 rounded text-sm font-medium border ${filterType === 'all' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}`}
                >
                  All Inventory
                </button>
                <button 
                  onClick={() => setFilterType('buynow')}
                  className={`px-4 py-2 rounded text-sm font-medium border ${filterType === 'buynow' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}`}
                >
                  Buy It Now
                </button>
                <button 
                  onClick={() => setFilterType('suv')}
                  className={`px-4 py-2 rounded text-sm font-medium border ${filterType === 'suv' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}`}
                >
                  SUVs & Trucks
                </button>
              </div>
            </div>

            {/* Results Grid */}
            <div className="flex items-center justify-between mb-4">
               <h2 className="text-xl font-bold text-gray-800">Vehicle Inventory <span className="text-gray-400 font-normal text-sm ml-2">({filteredVehicles.length} Vehicles)</span></h2>
               <div className="text-sm text-gray-600">Sort by: <span className="font-semibold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-white rounded shadow-sm">
                <h3 className="text-lg font-medium text-gray-900">No vehicles found</h3>
                <p className="text-gray-500 mt-2">Try adjusting your search terms or filters.</p>
              </div>
            )}
          </div>
        )}

        {currentView === 'detail' && selectedVehicle && (
          <VehicleDetail 
            vehicle={selectedVehicle} 
            onBack={handleBackToHome}
            onPlaceBid={handlePlaceBid}
          />
        )}

