interface VehicleDetailProps {
  vehicle: Vehicle;
  onBack: () => void;
  onPlaceBid: (amount: number) => void;
}

export const VehicleDetail: React.FC<VehicleDetailProps> = ({ vehicle, onBack, onPlaceBid }) => {
  const [bidAmount, setBidAmount] = useState<number>(vehicle.currentBid + 100);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isLoadingAnalysis, setIsLoadingAnalysis] = useState(false);
  const [mainImage, setMainImage] = useState(`https://picsum.photos/id/${vehicle.imageSeed}/800/600`);

  const handleGenerateAnalysis = async () => {
    setIsLoadingAnalysis(true);
    const result = await generateVehicleAnalysis(vehicle);
    setAnalysis(result);
    setIsLoadingAnalysis(false);
  };

  const handleBidSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bidAmount > vehicle.currentBid) {
      onPlaceBid(bidAmount);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      {/* Breadcrumb / Back */}
      <button onClick={onBack} className="flex items-center text-red-700 hover:text-red-900 mb-6 font-medium text-sm">
        ← Back to Search Results
      </button>

