            </div>
            <div className="flex gap-2 mt-2 overflow-x-auto p-2">
               {[0, 1, 2, 3].map((i) => (
                 <img 
                   key={i}
                   src={`https://picsum.photos/id/${vehicle.imageSeed + i}/200/150`}
                   className="h-20 w-32 object-cover cursor-pointer hover:opacity-80 rounded border border-gray-300"
                   onClick={() => setMainImage(`https://picsum.photos/id/${vehicle.imageSeed + i}/800/600`)}
                   alt={`Thumbnail ${i}`}
                 />
               ))}
            </div>
          </div>

          {/* Vehicle Information */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
            <div className="bg-gray-50 px-6 py-4 border-b border-gray-200">
