                >
                  SUVs & Trucks
                </button>
              </div>
            </div>

            {/* Results Grid */}
            <div className="flex items-center justify-between mb-4">
               <h2 className="text-xl font-bold text-gray-800">Vehicle Inventory <span className="text-gray-400 font-normal text-sm ml-2">({filteredVehicles.length} Vehicles)</span></h2>
               <div className="text-sm text-gray-600">Sort by: <span className="font-semibold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
