                  >
                    {isLoadingAnalysis ? 'Analyzing...' : 'Generate Report'}
                  </button>
                )}
             </div>
             <div className="p-8 relative z-10">
                {!analysis && !isLoadingAnalysis && (
                  <p className="text-indigo-400 text-center py-6 font-medium">
