                   <div className="prose prose-sm prose-indigo text-gray-700 max-w-none bg-white/50 p-6 rounded-2xl border border-indigo-50">
                     <div dangerouslySetInnerHTML={{ __html: analysis.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br />') }} />
                   </div>
                )}
             </div>
          </div>
        </div>

        {/* Right Column: Bidding Interface */}
        <div className="space-y-6">
           <div className="glass-panel p-6 rounded-[2rem] sticky top-28 border-t-[6px] border-t-red-500/80">
