                   <span className="text-4xl font-bold text-gray-900 tracking-tight">${vehicle.currentBid.toLocaleString()}</span>
                 </div>
                 {vehicle.buyNowPrice && (
                    <div className="flex justify-between items-center text-sm mt-3 pt-3 border-t border-gray-200">
                      <span className="text-gray-500 font-medium">Buy It Now Price</span>
                      <span className="font-bold text-blue-600 cursor-pointer hover:underline bg-blue-50 px-2 py-0.5 rounded-lg">${vehicle.buyNowPrice.toLocaleString()}</span>
