              <form onSubmit={handleBidSubmit} className="space-y-5">
                 <div>
                   <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Set Your Max Bid</label>
                   <div className="relative group">
                     <span className="absolute left-4 top-3.5 text-gray-400 font-bold text-lg">$</span>
                     <input 
                        type="number"
                        value={bidAmount}
                        onChange={(e) => setBidAmount(parseInt(e.target.value) || 0)}
                        min={vehicle.currentBid + 50}
                        step={50}
                        className="w-full pl-8 pr-4 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-4 focus:ring-red-100 focus:border-red-400 outline-none text-xl font-bold text-gray-800 transition-all shadow-inner"
                     />
