                 <button 
                   type="submit"
                   className="w-full bg-gradient-to-r from-red-600 to-red-500 text-white font-bold py-4 rounded-2xl hover:shadow-xl hover:shadow-red-500/30 hover:scale-[1.02] active:scale-[0.98] transition-all text-lg shadow-lg"
                 >
                   Place Bid
                 </button>
                 <button 
                   type="button"
                   className="w-full bg-white text-gray-600 font-bold py-3 rounded-2xl border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-all shadow-sm"
                 >
                   Add to Watchlist
