              </form>

              <div className="mt-8 pt-6 border-t border-gray-200/60">
                 <h4 className="font-bold text-gray-800 text-sm mb-4 uppercase tracking-wide">Sale Status</h4>
                 <div className="space-y-3 text-sm bg-gray-50/50 p-4 rounded-2xl border border-white/60">
                   <div className="flex justify-between">
                     <span className="text-gray-500">Sale Date</span>
                     <span className="text-gray-900 font-medium">Today</span>
                   </div>
                   <div className="flex justify-between">
                     <span className="text-gray-500">Time Left</span>
                     <span className="text-red-500 font-bold animate-pulse">Live Auction</span>
                   </div>
                   <div className="flex justify-between">
                     <span className="text-gray-500">Lane / Grid</span>
                     <span className="text-gray-900 font-medium">Lane A / Grid 104</span>
                   </div>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

