import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle } from './types';
import { MOCK_VEHICLES } from './constants';

type ViewState = 'home' | 'detail' | 'dashboard';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Initial load simulation
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  // Handle navigation with simulated loading
  const navigate = (view: ViewState) => {
    // Only show loading if changing views (or re-navigating to home which might refresh)
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    // Simulate network request duration
    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  };

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    // Simulate placing a bid
    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { ...v, currentBid: amount } : v
    );
    setVehicles(updatedVehicles);

    // Update selected vehicle reference
    setSelectedVehicle({ ...selectedVehicle, currentBid: amount });

    alert(`Bid of $${amount.toLocaleString()} placed successfully!`);
  };

  // Filter Logic
  const filteredVehicles = vehicles.filter(v => {
    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    if (filterType === 'all') return true;
    if (filterType === 'buynow') return v.buyNowPrice !== undefined;
    if (filterType === 'suv') return v.drive === 'AWD' || v.drive === '4WD'; // Rough approximation

    return true;
  });

  return (
    <div className="min-h-screen font-sans text-gray-900 pb-28 md:pb-0 bg-transparent selection:bg-red-200 selection:text-red-900">
      <Navbar onNavigate={(page) => navigate(page as ViewState)} activePage={currentView} />

      {/* Main Content Area */}
      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

            {/* Search & Filter Bar */}
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder="Find your next ride..." 
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setFilterType('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm ${filterType === 'all' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  All Inventory
                </button>
                <button 
                  onClick={() => setFilterType('buynow')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm ${filterType === 'buynow' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  Buy It Now
                </button>
                <button 
                  onClick={() => setFilterType('suv')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm ${filterType === 'suv' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  SUVs & Trucks
                </button>
              </div>
            </div>

            {/* Results Grid */}
            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">Vehicle Inventory <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span></h2>
               <div className="hidden sm:block text-sm text-gray-600 bg-white/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/40">Sort by: <span className="font-bold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {isLoading ? (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                 {[...Array(8)].map((_, i) => <VehicleCardSkeleton key={i} />)}
               </div>
            ) : filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 glass-panel rounded-[2rem]">
                <h3 className="text-xl font-bold text-gray-900">No vehicles found</h3>
                <p className="text-gray-500 mt-2">Try adjusting your search terms or filters.</p>
              </div>
            )}
          </div>
        )}

        {currentView === 'detail' && (
           isLoading ? (
             <VehicleDetailSkeleton />
           ) : (
             selectedVehicle && (
                <VehicleDetail 
                  vehicle={selectedVehicle} 
                  onBack={handleBackToHome}
                  onPlaceBid={handlePlaceBid}
                />
             )
           )
        )}

        {currentView === 'dashboard' && (
          isLoading ? (
            <DashboardSkeleton />
          ) : (
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
              <h1 className="text-3xl font-bold text-gray-900 mb-8">My Dashboard</h1>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                 <div className="glass-panel p-8 rounded-[2rem] hover:scale-105 transition-transform">
                   <h2 className="font-bold text-lg mb-4 text-red-600 uppercase tracking-wider text-xs">Active Bids</h2>
                   <p className="text-5xl font-bold text-gray-800 mb-2">2</p>
                   <p className="text-sm text-gray-500 font-medium">Total value: $46,000</p>
                 </div>
                 <div className="glass-panel p-8 rounded-[2rem] hover:scale-105 transition-transform">
                   <h2 className="font-bold text-lg mb-4 text-gray-500 uppercase tracking-wider text-xs">Watchlist</h2>
                   <p className="text-5xl font-bold text-gray-800 mb-2">5</p>
                   <p className="text-sm text-gray-500 font-medium">2 ending today</p>
                 </div>
                 <div className="glass-panel p-8 rounded-[2rem] hover:scale-105 transition-transform bg-gradient-to-br from-green-50/50 to-white/50">
                   <h2 className="font-bold text-lg mb-4 text-green-600 uppercase tracking-wider text-xs">Buying Power</h2>
                   <p className="text-5xl font-bold text-gray-800 mb-2">$150k</p>
                   <p className="text-sm text-green-600 mt-1 font-bold bg-green-100 px-3 py-1 rounded-full w-max">Active</p>
                 </div>
              </div>

              <div className="glass-panel rounded-[2rem] overflow-hidden">
                 <div className="bg-white/40 px-8 py-6 border-b border-white/40">
                   <h3 className="font-bold text-gray-800 text-lg">Recent Activity</h3>
                 </div>
                 <div className="divide-y divide-gray-100/50">
                    <div className="px-8 py-6 flex items-center justify-between hover:bg-white/30 transition-colors">
                      <div>
                        <span className="block font-bold text-gray-900 text-lg">Bid Placed - 2021 Ford F-150</span>
                        <span className="text-sm text-gray-500 font-medium">Today, 10:42 AM</span>
                      </div>
                      <span className="bg-green-100 text-green-800 px-4 py-1.5 rounded-full text-xs font-bold shadow-sm">Winning</span>
                    </div>
                    <div className="px-8 py-6 flex items-center justify-between hover:bg-white/30 transition-colors">
                      <div>
                        <span className="block font-bold text-gray-900 text-lg">Outbid - 2023 Tesla Model 3</span>
                        <span className="text-sm text-gray-500 font-medium">Yesterday, 4:15 PM</span>
                      </div>
                      <span className="bg-red-100 text-red-800 px-4 py-1.5 rounded-full text-xs font-bold shadow-sm">Outbid</span>
                    </div>
                 </div>
              </div>
            </div>
          )
        )}
      </main>

      {/* Footer */}
      <footer className="glass-panel border-t border-white/40 mt-12 backdrop-blur-xl">
        <div className="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 md:grid-cols-4 gap-12">
           <div>
             <span className="text-2xl font-bold text-gray-900 tracking-tighter italic">AutoBid<span className="text-red-600">AI</span></span>
             <p className="mt-4 text-sm text-gray-500 font-medium leading-relaxed">The most intelligent way to buy salvage and used vehicles. Powered by AI and Liquid Design.</p>
           </div>
           <div>
             <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">Auctions</h4>
             <ul className="space-y-3 text-sm text-gray-600 font-medium">
               <li><a href="#" className="hover:text-red-600 transition-colors">Today's Auctions</a></li>
               <li><a href="#" className="hover:text-red-600 transition-colors">Join Auction</a></li>
               <li><a href="#" className="hover:text-red-600 transition-colors">Auction Calendar</a></li>
             </ul>
           </div>
           <div>
             <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">Services</h4>
             <ul className="space-y-3 text-sm text-gray-600 font-medium">
               <li><a href="#" className="hover:text-red-600 transition-colors">Vehicle Transportation</a></li>
               <li><a href="#" className="hover:text-red-600 transition-colors">Condition Reports</a></li>
               <li><a href="#" className="hover:text-red-600 transition-colors">Broker Services</a></li>
