import { analyzeVehicleImage } from '../services/geminiService';

interface SellCarProps {
  onNavigate: (page: string) => void;
}

export const SellCar: React.FC<SellCarProps> = ({ onNavigate }) => {
  const [step, setStep] = useState(1);
  const [isDragging, setIsDragging] = useState(false);
  const [isValidating, setIsValidating] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);

  // Step 1: Car Image
  const [image, setImage] = useState<string | null>(null);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('image/jpeg');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Step 3: Fine Image
  const [fineImage, setFineImage] = useState<string | null>(null);
  const fineInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    // Step 2 Data
    year: '',
    make: '',
    model: '',
    vin: '',
    odometer: '',
    price: '',
    engine: '',
    topSpeed: '',
    mpg: '',
    description: '',

    // Step 3 Data
    hasFine: 'no',
    isFirstOwner: 'yes',

    // Step 4 Data
    ownerName: '',
    phoneNumber: '',
    streetAddress: '',
    city: '',
    state: '',
    zipCode: '',

    // Step 5 Data
    scheduleType: 'auto', // 'auto' | 'manual'
    auctionDate: '',
    auctionStartTime: '',
    auctionEndTime: ''
  });

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      processFile(files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      processFile(files[0]);
    }
  };

  const processFile = (file: File) => {
    setValidationError(null);
    if (!file.type.startsWith('image/')) {
      setValidationError("Please upload an image file.");
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const result = e.target?.result as string;
      setImage(result);

      const base64Data = result.split(',')[1];
      setImageBase64(base64Data);
      setImageMime(file.type);

      analyzeImage(base64Data, file.type);
    };
    reader.readAsDataURL(file);
  };

  const handleFineImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
        const file = files[0];
        const reader = new FileReader();
        reader.onload = (e) => {
            setFineImage(e.target?.result as string);
        };
        reader.readAsDataURL(file);
    }
  };

  const analyzeImage = async (base64: string, mime: string) => {
    setIsValidating(true);
    try {
      const analysis = await analyzeVehicleImage(base64, mime);

      if (!analysis.isVehicle) {
        setValidationError("Our AI did not detect a car in this image. Please upload a clear picture of a vehicle.");
        setImage(null);
        setImageBase64(null);
      } else {
        setValidationError(null);
        setFormData(prev => ({
            ...prev,
            make: analysis.make || prev.make,
            model: analysis.model || prev.model,
            year: analysis.year || prev.year,
            engine: analysis.engine || prev.engine,
            topSpeed: analysis.topSpeed || prev.topSpeed,
            mpg: analysis.mpg || prev.mpg,
        }));
      }
    } catch (err) {
      console.error(err);
      setValidationError("Could not validate image. Please try again.");
    } finally {
      setIsValidating(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate submission
    setTimeout(() => {
        setStep(6); // Success state
    }, 1000);
  };

  // Progress Bar Width Calculation
  const getProgressWidth = () => {
      switch(step) {
          case 1: return '20%';
          case 2: return '40%';
          case 3: return '60%';
          case 4: return '80%';
          case 5: return '100%';
          default: return '100%';
      }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <div className="glass-panel p-8 rounded-[2.5rem] relative overflow-hidden">

        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-2 bg-gray-100">
           <div 
             className="h-full bg-gradient-to-r from-red-600 to-orange-500 transition-all duration-500"
             style={{ width: getProgressWidth() }}
           ></div>
        </div>

        {/* STEP 1: Upload */}
        {step === 1 && (
          <div className="mt-6 animate-fade-in-up">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Sell Your Vehicle</h2>
            <p className="text-gray-500 mb-8">Step 1 of 5: Upload a photo. Our AI will identify your vehicle.</p>

            <div 
              className={`border-4 border-dashed rounded-[2rem] p-12 text-center transition-all cursor-pointer relative overflow-hidden ${
                isDragging ? 'border-red-500 bg-red-50' : 'border-gray-300 hover:border-red-300 hover:bg-white/50'
              } ${image ? 'border-green-400 bg-green-50/30' : ''}`}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onClick={() => !isValidating && !image && fileInputRef.current?.click()}
            >
               <input 
                 type="file" 
                 ref={fileInputRef}
                 className="hidden" 
                 accept="image/*"
                 onChange={handleFileSelect}
               />

               {isValidating ? (
                  <div className="flex flex-col items-center justify-center py-10">
                     <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-600 mb-4"></div>
                     <p className="text-lg font-bold text-gray-700">AI is analyzing vehicle specs...</p>
                  </div>
               ) : image ? (
                 <div className="relative group">
                    <img src={image} alt="Upload preview" className="max-h-80 mx-auto rounded-xl shadow-lg" />
                    <button 
                      onClick={(e) => {
                          e.stopPropagation();
                          setImage(null);
                          setImageBase64(null);
                          setFormData(prev => ({ 
                              ...prev, 
                              make: '', model: '', year: '', engine: '', topSpeed: '', mpg: '' 
                          })); 
                      }}
                      className="absolute top-2 right-2 bg-red-600 text-white p-2 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity hover:scale-110"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                    <div className="mt-4 flex flex-col items-center justify-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 font-bold bg-green-100 py-2 px-4 rounded-full mx-auto w-max">
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                          Vehicle Identified
                        </div>
                        {formData.make && (
                          <div className="text-center">
                              <p className="text-gray-800 font-bold text-lg">
                                {formData.year} {formData.make} {formData.model}
                              </p>
                              <p className="text-gray-500 text-sm">{formData.engine}</p>
                          </div>
                        )}
                    </div>
                 </div>
               ) : (
                 <div className="py-10">
                    <div className="w-20 h-20 bg-red-100 text-red-500 rounded-full flex items-center justify-center mx-auto mb-4">
                        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    </div>
                    <p className="text-xl font-bold text-gray-700">Drag & Drop your car photo here</p>
                    <p className="text-gray-400 mt-2">or click to browse</p>
                 </div>
               )}
            </div>

            {validationError && (
                <div className="mt-4 p-4 bg-red-100 text-red-700 rounded-xl flex items-center gap-3 animate-shake">
                    <svg className="w-6 h-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    <span className="font-medium">{validationError}</span>
                </div>
            )}

            <div className="mt-8 flex justify-end">
                <button 
                  onClick={() => setStep(2)}
                  disabled={!image || isValidating}
                  className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-105 transition-all"
                >
                  Next Step
                </button>
            </div>
          </div>
        )}

        {/* STEP 2: Vehicle Details */}
        {step === 2 && (
            <div className="mt-6 animate-fade-in-right">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Vehicle Details</h2>
                <p className="text-gray-500 mb-8">Step 2 of 5: Review and verify vehicle specifications.</p>

                <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Year</label>
                            <input 
                                type="number" 
                                name="year"
                                value={formData.year}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="2023"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Make</label>
                            <input 
                                type="text" 
                                name="make"
                                value={formData.make}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="Toyota"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Model</label>
                            <input 
                                type="text" 
                                name="model"
                                value={formData.model}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="Camry"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">VIN <span className="text-gray-400 font-normal ml-1">(Optional)</span></label>
                            <input 
                                type="text" 
                                name="vin"
                                value={formData.vin}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="17 characters"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Engine</label>
                            <input 
                                type="text" 
                                name="engine"
                                value={formData.engine}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="3.5L V6"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Mileage (Odometer)</label>
                            <input 
                                type="number" 
                                name="odometer"
                                value={formData.odometer}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="45000"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                         <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Top Speed</label>
                            <input 
                                type="text" 
                                name="topSpeed"
                                value={formData.topSpeed}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="135 mph"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Avg MPG</label>
                            <input 
                                type="text" 
                                name="mpg"
                                value={formData.mpg}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="28 mpg"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Vehicle Description</label>
                        <textarea 
                            name="description"
                            value={formData.description}
                            onChange={handleInputChange}
                            rows={3}
                            className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all resize-none"
                            placeholder="Describe any issues, modifications, recent repairs..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Asking Price (₹ INR)</label>
                        <div className="relative">
                            <span className="absolute left-5 top-3.5 text-gray-500 font-bold">₹</span>
                            <input 
                                type="number" 
                                name="price"
                                value={formData.price}
                                onChange={handleInputChange}
                                className="w-full pl-10 pr-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all text-lg font-bold"
                                placeholder="15,00,000"
                            />
                        </div>
                    </div>

                    <div className="flex justify-between mt-8 pt-4 border-t border-gray-200/50">
                        <button 
                            type="button"
                            onClick={() => setStep(1)}
                            className="text-gray-500 font-bold px-6 py-3 hover:text-gray-700 transition-colors"
                        >
                            Back
                        </button>
                        <button 
                            type="button"
                            onClick={() => setStep(3)}
                            className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 hover:scale-105 transition-all"
                        >
                            Next Step
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* STEP 3: Info (Fines & First Owner) */}
        {step === 3 && (
            <div className="mt-6 animate-fade-in-right">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Additional Info</h2>
                <p className="text-gray-500 mb-8">Step 3 of 5: Legal and ownership details.</p>

                <div className="space-y-8">
                    {/* Fines Question */}
                    <div className="bg-white/40 p-6 rounded-2xl border border-white/60">
                        <label className="block text-lg font-bold text-gray-800 mb-4">Is there any pending fine / challan?</label>
                        <div className="flex gap-6 mb-4">
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.hasFine === 'yes' ? 'bg-red-50 border-red-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="hasFine" 
                                    value="yes" 
                                    checked={formData.hasFine === 'yes'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-red-600 focus:ring-red-500"
                                />
                                <span className="font-bold text-gray-700">Yes</span>
                            </label>
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.hasFine === 'no' ? 'bg-green-50 border-green-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="hasFine" 
                                    value="no" 
                                    checked={formData.hasFine === 'no'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-green-600 focus:ring-green-500"
                                />
                                <span className="font-bold text-gray-700">No</span>
                            </label>
                        </div>

                        {formData.hasFine === 'yes' && (
                            <div className="animate-fade-in-down mt-4 p-4 bg-red-50 rounded-xl border border-red-100">
                                <p className="text-sm font-bold text-red-700 mb-3">Please upload a picture of the fines/challan:</p>
                                <div 
                                    className="border-2 border-dashed border-red-300 bg-white rounded-lg p-6 text-center cursor-pointer hover:bg-red-50 transition-colors"
                                    onClick={() => fineInputRef.current?.click()}
                                >
                                    <input 
                                        type="file" 
                                        ref={fineInputRef}
                                        className="hidden" 
                                        accept="image/*"
                                        onChange={handleFineImageSelect}
                                    />
                                    {fineImage ? (
                                        <div className="flex items-center justify-center gap-2 text-green-600 font-bold">
                                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                                            Image Uploaded
                                        </div>
                                    ) : (
                                        <span className="text-red-500 text-sm font-medium">Click to upload document</span>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* First Owner Question */}
                    <div className="bg-white/40 p-6 rounded-2xl border border-white/60">
                        <label className="block text-lg font-bold text-gray-800 mb-4">Are you the first owner of the vehicle?</label>
                        <div className="flex gap-6">
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.isFirstOwner === 'yes' ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="isFirstOwner" 
                                    value="yes" 
                                    checked={formData.isFirstOwner === 'yes'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-blue-600 focus:ring-blue-500"
                                />
                                <span className="font-bold text-gray-700">Yes</span>
                            </label>
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.isFirstOwner === 'no' ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="isFirstOwner" 
                                    value="no" 
                                    checked={formData.isFirstOwner === 'no'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-blue-600 focus:ring-blue-500"
                                />
                                <span className="font-bold text-gray-700">No</span>
                            </label>
                        </div>
                    </div>

                    <div className="flex justify-between mt-8 pt-4 border-t border-gray-200/50">
                        <button 
                            type="button"
                            onClick={() => setStep(2)}
                            className="text-gray-500 font-bold px-6 py-3 hover:text-gray-700 transition-colors"
                        >
                            Back
                        </button>
                        <button 
                            type="button"
                            onClick={() => {
                                if (formData.hasFine === 'yes' && !fineImage) {
                                    alert("Please upload the fine/challan image.");
                                    return;
                                }
                                setStep(4);
                            }}
                            className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 hover:scale-105 transition-all"
                        >
                            Next Step
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* STEP 4: Owner Address */}
        {step === 4 && (
            <div className="mt-6 animate-fade-in-right">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Final Details</h2>
                <p className="text-gray-500 mb-8">Step 4 of 5: Where is the vehicle located?</p>

                <div className="space-y-6">
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Owner Name</label>
                        <input 
                            type="text" 
                            name="ownerName"
                            value={formData.ownerName}
                            onChange={handleInputChange}
                            className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                            placeholder="John Doe"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Phone Number</label>
                        <input 
                            type="tel" 
                            name="phoneNumber"
                            value={formData.phoneNumber}
                            onChange={handleInputChange}
                            className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                            placeholder="(555) 123-4567"
                            required
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Street Address</label>
                        <input 
                            type="text" 
                            name="streetAddress"
                            value={formData.streetAddress}
                            onChange={handleInputChange}
                            className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                            placeholder="123 Main St"
                            required
                        />
                    </div>

                    <div className="grid grid-cols-6 gap-4">
                        <div className="col-span-3">
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">City</label>
                            <input 
                                type="text" 
                                name="city"
                                value={formData.city}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="New York"
                                required
                            />
                        </div>
                        <div className="col-span-3">
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">State / Zip</label>
                            <div className="flex gap-2">
                                <input 
                                    type="text" 
                                    name="state"
                                    value={formData.state}
                                    onChange={handleInputChange}
                                    className="w-1/2 px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
