import React, { useEffect, useState } from 'react';
import { Vehicle, VehicleStatus } from '../types';

interface VehicleCardProps {
  vehicle: Vehicle;
  onClick: (vehicle: Vehicle) => void;
}

export const VehicleCard: React.FC<VehicleCardProps> = ({ vehicle, onClick }) => {
  const [timeLeft, setTimeLeft] = useState<string>('');
  // We calculate display status locally based on time remaining
  const [displayStatus, setDisplayStatus] = useState<string>(vehicle.status);
  const [isLive, setIsLive] = useState<boolean>(false);

  useEffect(() => {
    const calculateTimeLeft = () => {
      const now = Date.now();
      const difference = vehicle.endTime - now;
      const threeHoursMs = 3 * 60 * 60 * 1000;

      if (difference <= 0) {
        setDisplayStatus('Sold');
        setIsLive(false);
        return 'Ended';
      }

      // Live Logic: 10 mins to 3 hours (Actually 0 to 3 hours based on request flow)
      // "from 10 minutes to 3 hours before that it is countable as upcoming bids" implies:
      // > 3 hours = Upcoming
      // <= 3 hours = Live
      if (difference <= threeHoursMs) {
         setDisplayStatus('Live Auction');
         setIsLive(true);
      } else {
         setDisplayStatus('Upcoming');
         setIsLive(false);
      }

      const hours = Math.floor((difference / (1000 * 60 * 60)));
      const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((difference % (1000 * 60)) / 1000);

      return `${hours}h ${minutes}m ${seconds}s`;
    };

    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);

    setTimeLeft(calculateTimeLeft());

    return () => clearInterval(timer);
  }, [vehicle.endTime]);

  return (
    <div 
      className="glass-card rounded-3xl overflow-hidden flex flex-col cursor-pointer h-full transition-all duration-300 hover:-translate-y-2 hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.1)] group"
      onClick={() => onClick(vehicle)}
    >
      <div className="relative h-56 w-full overflow-hidden">
        <img 
          src={`https://picsum.photos/id/${vehicle.imageSeed}/400/300`} 
          alt={`${vehicle.year} ${vehicle.make}`} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-60"></div>
        <div className="absolute top-3 left-3">
           <span className={`px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full text-white shadow-lg backdrop-blur-md border border-white/20 ${isLive ? 'bg-red-600/90 animate-pulse' : 'bg-blue-600/90'}`}>
             {displayStatus}
           </span>
        </div>
        <div className="absolute bottom-3 right-3 bg-white/20 backdrop-blur-md border border-white/30 text-white text-xs font-medium px-3 py-1 rounded-full shadow-lg">
          {vehicle.odometer.toLocaleString()} mi
        </div>
      </div>

      <div className="p-5 flex-1 flex flex-col relative">
        <div className="absolute -top-6 right-4 bg-white rounded-2xl p-2 shadow-lg border border-gray-100">
             <div className="text-[10px] text-gray-400 font-bold uppercase text-center leading-none">BID</div>
             <div className="text-gray-900 font-bold text-lg leading-tight">₹{(vehicle.currentBid/1000).toFixed(1)}k</div>
        </div>

        <h3 className="text-xl font-bold text-gray-800 leading-tight mb-1 group-hover:text-red-600 transition-colors">
          {vehicle.year} {vehicle.make} {vehicle.model}
        </h3>
        <p className="text-xs text-gray-500 mb-4 font-medium tracking-wide">VIN: {vehicle.vin}</p>

        <div className="grid grid-cols-2 gap-y-3 gap-x-2 text-sm mb-5 bg-white/40 rounded-2xl p-3 border border-white/50">
          <div>
            <span className="block text-gray-400 text-[10px] uppercase font-bold">Damage</span>
            <span className="font-semibold text-gray-700 text-xs truncate">{vehicle.primaryDamage}</span>
          </div>
          <div>
            <span className="block text-gray-400 text-[10px] uppercase font-bold">Retail Est.</span>
            <span className="font-semibold text-gray-700 text-xs">₹{vehicle.estRetailValue.toLocaleString()}</span>
          </div>
          <div className="col-span-2">
            <span className="block text-gray-400 text-[10px] uppercase font-bold">Location</span>
            <span className="font-semibold text-gray-700 text-xs truncate">{vehicle.location}</span>
          </div>
        </div>

        <div className="mt-auto">
          <div className="flex justify-between items-center bg-gray-50/50 rounded-full px-4 py-2 border border-white/60">
            <span className="text-gray-500 text-xs font-medium">Ends in</span>
            <span className={`font-mono font-bold text-sm ${isLive ? 'text-red-600' : 'text-gray-700'}`}>
              {timeLeft}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle } from './types';
import { MOCK_VEHICLES } from './constants';

type ViewState = 'home' | 'detail' | 'dashboard' | 'auth' | 'sell';
type AuctionFilter = 'all' | 'live' | 'upcoming';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // New Filter State
  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');

  const [isLoading, setIsLoading] = useState(true);

  // Initial load simulation
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  // Handle navigation with simulated loading
  const navigate = (view: string) => {
    // Handle special auth routes
    if (view === 'login') {
        setAuthMode('login');
        handleViewChange('auth');
        return;
    }
    if (view === 'register') {
        setAuthMode('register');
        handleViewChange('auth');
        return;
    }

    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    // Simulate network request duration
    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handleLoginSuccess = () => {
      navigate('dashboard');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    // Simulate placing a bid
    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { ...v, currentBid: amount } : v
    );
    setVehicles(updatedVehicles);

    // Update selected vehicle reference
    setSelectedVehicle({ ...selectedVehicle, currentBid: amount });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  // Filter Logic
  const filteredVehicles = vehicles.filter(v => {
    // 1. Search Query
    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    // 2. Auction Status Filter (Live vs Upcoming)
    const now = Date.now();
    const threeHoursMs = 3 * 60 * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        // Live: Time left is between 0 and 3 hours
        return timeLeft > 0 && timeLeft <= threeHoursMs;
    }
    if (auctionFilter === 'upcoming') {
        // Upcoming: Time left is more than 3 hours
        return timeLeft > threeHoursMs;
    }

    // 'all' includes everything (that hasn't ended, usually, but for demo we show all active)
    return timeLeft > 0;
  });

  return (
    <div className="min-h-screen font-sans text-gray-900 pb-28 md:pb-32 bg-transparent selection:bg-red-200 selection:text-red-900">
      <Navbar onNavigate={navigate} activePage={currentView} />

      {/* Main Content Area */}
      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

            {/* Search & Filter Bar */}
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder="Find your next ride..." 
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              {/* Status Filters */}
              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setAuctionFilter('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'all' ? 'bg-gradient-to-r from-gray-800 to-gray-700 text-white shadow-gray-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-gray-900'}`}
                >
                  All Auctions
                </button>
                <button 
                  onClick={() => setAuctionFilter('live')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'live' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  <span className={`inline-block w-2 h-2 rounded-full mr-2 ${auctionFilter === 'live' ? 'bg-white animate-pulse' : 'bg-red-500'}`}></span>
                  Live Auctions
                </button>
                <button 
                  onClick={() => setAuctionFilter('upcoming')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'upcoming' ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-blue-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-blue-500'}`}
                >
                  Upcoming
                </button>
              </div>
            </div>

            {/* Results Grid */}
            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">
                   {auctionFilter === 'all' && 'Vehicle Inventory'}
                   {auctionFilter === 'live' && 'Live Auctions'}
                   {auctionFilter === 'upcoming' && 'Upcoming Auctions'}
                   <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span>
