  const [isValidating, setIsValidating] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);

  // Step 1: Car Image
  const [image, setImage] = useState<string | null>(null);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('image/jpeg');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Step 3: Fine Image
  const [fineImage, setFineImage] = useState<string | null>(null);
  const fineInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    // Step 2 Data
    year: '',
    make: '',
    model: '',
    vin: '',
    odometer: '',
    price: '',
    engine: '',
    topSpeed: '',
    mpg: '',
    description: '',

    // Step 3 Data
    hasFine: 'no',
    isFirstOwner: 'yes',

    // Step 4 Data
    ownerName: '',
    phoneNumber: '',
    streetAddress: '',
    city: '',
    state: '',
    zipCode: '',

    // Step 5 Data
    scheduleType: 'auto', // 'auto' | 'manual'
    auctionDate: '',      // Start Date
    auctionStartTime: '', // Start Time
    auctionEndDate: '',   // End Date
    auctionEndTime: ''    // End Time
  });

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      processFile(files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      processFile(files[0]);
    }
  };

  const processFile = (file: File) => {
    setValidationError(null);
    if (!file.type.startsWith('image/')) {
      setValidationError("Please upload an image file.");
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const result = e.target?.result as string;
      setImage(result);

      const base64Data = result.split(',')[1];
      setImageBase64(base64Data);
      setImageMime(file.type);

      analyzeImage(base64Data, file.type);
    };
    reader.readAsDataURL(file);
  };

  const handleFineImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
        const file = files[0];
        const reader = new FileReader();
        reader.onload = (e) => {
            setFineImage(e.target?.result as string);
        };
        reader.readAsDataURL(file);
    }
  };

  const analyzeImage = async (base64: string, mime: string) => {
    setIsValidating(true);
    try {
      const analysis = await analyzeVehicleImage(base64, mime);

      if (!analysis.isVehicle) {
        setValidationError("Our AI did not detect a car in this image. Please upload a clear picture of a vehicle.");
        setImage(null);
        setImageBase64(null);
      } else {
        setValidationError(null);
        setFormData(prev => ({
            ...prev,
            make: analysis.make || prev.make,
            model: analysis.model || prev.model,
            year: analysis.year || prev.year,
            engine: analysis.engine || prev.engine,
            topSpeed: analysis.topSpeed || prev.topSpeed,
            mpg: analysis.mpg || prev.mpg,
        }));
      }
    } catch (err) {
      console.error(err);
      setValidationError("Could not validate image. Please try again.");
    } finally {
      setIsValidating(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (formData.scheduleType === 'manual') {
        const start = new Date(`${formData.auctionDate}T${formData.auctionStartTime}`);
        const end = new Date(`${formData.auctionEndDate}T${formData.auctionEndTime}`);

        if (isNaN(start.getTime()) || isNaN(end.getTime())) {
            // Wait for inputs
            return; 
        }

        if (end <= start) {
            alert("Auction end time must be after the start time.");
            return;
        }
    }

    // Simulate submission
    setTimeout(() => {
        setStep(6); // Success state
    }, 1000);
  };

  // Progress Bar Width Calculation
  const getProgressWidth = () => {
      switch(step) {
          case 1: return '20%';
          case 2: return '40%';
          case 3: return '60%';
          case 4: return '80%';
          case 5: return '100%';
          default: return '100%';
      }
  };

  // Calculate Duration for display
  const getDurationDisplay = () => {
      if (!formData.auctionDate || !formData.auctionStartTime || !formData.auctionEndDate || !formData.auctionEndTime) return 'Select start and end times';

      const start = new Date(`${formData.auctionDate}T${formData.auctionStartTime}`);
      const end = new Date(`${formData.auctionEndDate}T${formData.auctionEndTime}`);

      if (isNaN(start.getTime()) || isNaN(end.getTime())) return 'Invalid date';

      const diffMs = end.getTime() - start.getTime();
      if (diffMs <= 0) return 'End time must be after start time';

      const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
      const hours = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));

      let durationStr = '';
      if (days > 0) durationStr += `${days} Days `;
      if (hours > 0) durationStr += `${hours} Hours `;
      if (minutes > 0) durationStr += `${minutes} Mins`;

      return durationStr || '0 Mins';
  };

  // Generate 30-minute time slots for the dropdown
  const generateTimeSlots = () => {
    const slots = [];
    for (let i = 0; i < 24; i++) {
      for (let j = 0; j < 60; j += 30) {
        const hour = i.toString().padStart(2, '0');
        const minute = j.toString().padStart(2, '0');
        const timeValue = `${hour}:${minute}`;

        const ampm = i >= 12 ? 'PM' : 'AM';
        const displayHour = i % 12 || 12;
        const displayTime = `${displayHour}:${minute} ${ampm}`;

        slots.push({ value: timeValue, label: displayTime });
      }
    }
    return slots;
  };

  const timeSlots = generateTimeSlots();
  const today = new Date().toISOString().split('T')[0];

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <div className="glass-panel p-8 rounded-[2.5rem] relative overflow-hidden">

        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-2 bg-gray-100">
           <div 
             className="h-full bg-gradient-to-r from-red-600 to-orange-500 transition-all duration-500"
             style={{ width: getProgressWidth() }}
           ></div>
        </div>

        {/* STEP 1: Upload */}
        {step === 1 && (
          <div className="mt-6 animate-fade-in-up">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Sell Your Vehicle</h2>
            <p className="text-gray-500 mb-8">Step 1 of 5: Upload a photo. Our AI will identify your vehicle.</p>

            <div 
              className={`border-4 border-dashed rounded-[2rem] p-12 text-center transition-all cursor-pointer relative overflow-hidden ${
                isDragging ? 'border-red-500 bg-red-50' : 'border-gray-300 hover:border-red-300 hover:bg-white/50'
              } ${image ? 'border-green-400 bg-green-50/30' : ''}`}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onClick={() => !isValidating && !image && fileInputRef.current?.click()}
            >
               <input 
                 type="file" 
                 ref={fileInputRef}
                 className="hidden" 
                 accept="image/*"
                 onChange={handleFileSelect}
               />

               {isValidating ? (
                  <div className="flex flex-col items-center justify-center py-10">
                     <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-600 mb-4"></div>
                     <p className="text-lg font-bold text-gray-700">AI is analyzing vehicle specs...</p>
                  </div>
               ) : image ? (
                 <div className="relative group">
                    <img src={image} alt="Upload preview" className="max-h-80 mx-auto rounded-xl shadow-lg" />
                    <button 
                      onClick={(e) => {
                          e.stopPropagation();
                          setImage(null);
                          setImageBase64(null);
                          setFormData(prev => ({ 
                              ...prev, 
                              make: '', model: '', year: '', engine: '', topSpeed: '', mpg: '' 
                          })); 
                      }}
                      className="absolute top-2 right-2 bg-red-600 text-white p-2 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity hover:scale-110"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                    <div className="mt-4 flex flex-col items-center justify-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 font-bold bg-green-100 py-2 px-4 rounded-full mx-auto w-max">
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                          Vehicle Identified
                        </div>
                        {formData.make && (
                          <div className="text-center">
                              <p className="text-gray-800 font-bold text-lg">
                                {formData.year} {formData.make} {formData.model}
