                        <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    </div>
                    <p className="text-xl font-bold text-gray-700">Drag & Drop your car photo here</p>
                    <p className="text-gray-400 mt-2">or click to browse</p>
                 </div>
               )}
            </div>

            {validationError && (
                <div className="mt-4 p-4 bg-red-100 text-red-700 rounded-xl flex items-center gap-3 animate-shake">
                    <svg className="w-6 h-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                    <span className="font-medium">{validationError}</span>
                </div>
            )}

            <div className="mt-8 flex justify-end">
                <button 
                  onClick={() => setStep(2)}
                  disabled={!image || isValidating}
                  className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 disabled:opacity-50 disabled:cursor-not-allowed hover:scale-105 transition-all"
                >
                  Next Step
                </button>
            </div>
          </div>
        )}

        {/* STEP 2: Vehicle Details */}
        {step === 2 && (
            <div className="mt-6 animate-fade-in-right">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Vehicle Details</h2>
                <p className="text-gray-500 mb-8">Step 2 of 5: Review and verify vehicle specifications.</p>

                <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Year</label>
                            <input 
                                type="number" 
                                name="year"
                                value={formData.year}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="2023"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Make</label>
                            <input 
                                type="text" 
                                name="make"
                                value={formData.make}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="Toyota"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Model</label>
                            <input 
                                type="text" 
                                name="model"
                                value={formData.model}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="Camry"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">VIN <span className="text-gray-400 font-normal ml-1">(Optional)</span></label>
                            <input 
                                type="text" 
                                name="vin"
                                value={formData.vin}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="17 characters"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Engine</label>
                            <input 
                                type="text" 
                                name="engine"
                                value={formData.engine}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="3.5L V6"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Mileage (Odometer)</label>
                            <input 
                                type="number" 
                                name="odometer"
                                value={formData.odometer}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="45000"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                         <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Top Speed</label>
                            <input 
                                type="text" 
                                name="topSpeed"
                                value={formData.topSpeed}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="135 mph"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Avg MPG</label>
                            <input 
                                type="text" 
                                name="mpg"
                                value={formData.mpg}
                                onChange={handleInputChange}
                                className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all"
                                placeholder="28 mpg"
                            />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Vehicle Description</label>
                        <textarea 
                            name="description"
                            value={formData.description}
                            onChange={handleInputChange}
                            rows={3}
                            className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all resize-none"
                            placeholder="Describe any issues, modifications, recent repairs..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Asking Price (₹ INR)</label>
                        <div className="relative">
                            <span className="absolute left-5 top-3.5 text-gray-500 font-bold">₹</span>
                            <input 
                                type="number" 
                                name="price"
                                value={formData.price}
                                onChange={handleInputChange}
                                className="w-full pl-10 pr-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none transition-all text-lg font-bold"
                                placeholder="15,00,000"
                            />
                        </div>
                    </div>

                    <div className="flex justify-between mt-8 pt-4 border-t border-gray-200/50">
                        <button 
                            type="button"
                            onClick={() => setStep(1)}
                            className="text-gray-500 font-bold px-6 py-3 hover:text-gray-700 transition-colors"
                        >
                            Back
                        </button>
                        <button 
                            type="button"
                            onClick={() => setStep(3)}
                            className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 hover:scale-105 transition-all"
                        >
                            Next Step
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* STEP 3: Info (Fines & First Owner) */}
        {step === 3 && (
            <div className="mt-6 animate-fade-in-right">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Additional Info</h2>
                <p className="text-gray-500 mb-8">Step 3 of 5: Legal and ownership details.</p>

                <div className="space-y-8">
                    {/* Fines Question */}
                    <div className="bg-white/40 p-6 rounded-2xl border border-white/60">
                        <label className="block text-lg font-bold text-gray-800 mb-4">Is there any pending fine / challan?</label>
                        <div className="flex gap-6 mb-4">
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.hasFine === 'yes' ? 'bg-red-50 border-red-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="hasFine" 
                                    value="yes" 
                                    checked={formData.hasFine === 'yes'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-red-600 focus:ring-red-500"
                                />
                                <span className="font-bold text-gray-700">Yes</span>
                            </label>
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.hasFine === 'no' ? 'bg-green-50 border-green-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="hasFine" 
                                    value="no" 
                                    checked={formData.hasFine === 'no'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-green-600 focus:ring-green-500"
                                />
                                <span className="font-bold text-gray-700">No</span>
                            </label>
                        </div>

                        {formData.hasFine === 'yes' && (
                            <div className="animate-fade-in-down mt-4 p-4 bg-red-50 rounded-xl border border-red-100">
                                <p className="text-sm font-bold text-red-700 mb-3">Please upload a picture of the fines/challan:</p>
                                <div 
                                    className="border-2 border-dashed border-red-300 bg-white rounded-lg p-6 text-center cursor-pointer hover:bg-red-50 transition-colors"
                                    onClick={() => fineInputRef.current?.click()}
                                >
                                    <input 
                                        type="file" 
                                        ref={fineInputRef}
                                        className="hidden" 
                                        accept="image/*"
                                        onChange={handleFineImageSelect}
                                    />
                                    {fineImage ? (
                                        <div className="flex items-center justify-center gap-2 text-green-600 font-bold">
                                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                                            Image Uploaded
                                        </div>
                                    ) : (
                                        <span className="text-red-500 text-sm font-medium">Click to upload document</span>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* First Owner Question */}
                    <div className="bg-white/40 p-6 rounded-2xl border border-white/60">
                        <label className="block text-lg font-bold text-gray-800 mb-4">Are you the first owner of the vehicle?</label>
                        <div className="flex gap-6">
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.isFirstOwner === 'yes' ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="isFirstOwner" 
                                    value="yes" 
                                    checked={formData.isFirstOwner === 'yes'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-blue-600 focus:ring-blue-500"
                                />
                                <span className="font-bold text-gray-700">Yes</span>
                            </label>
                            <label className={`flex items-center gap-3 px-6 py-3 rounded-xl cursor-pointer transition-all border ${formData.isFirstOwner === 'no' ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-200 hover:border-gray-300'}`}>
                                <input 
                                    type="radio" 
                                    name="isFirstOwner" 
                                    value="no" 
                                    checked={formData.isFirstOwner === 'no'}
                                    onChange={handleInputChange}
                                    className="w-5 h-5 text-blue-600 focus:ring-blue-500"
                                />
