import React, { useEffect, useState } from 'react';
import { Vehicle, VehicleStatus } from '../types';

interface VehicleCardProps {
  vehicle: Vehicle;
  onClick: (vehicle: Vehicle) => void;
}

export const VehicleCard: React.FC<VehicleCardProps> = ({ vehicle, onClick }) => {
  const [timeLeft, setTimeLeft] = useState<string>('');
  // We calculate display status locally based on time remaining
  const [displayStatus, setDisplayStatus] = useState<string>(vehicle.status);
  const [isLive, setIsLive] = useState<boolean>(false);

  useEffect(() => {
    const calculateTimeLeft = () => {
      const now = Date.now();
      const difference = vehicle.endTime - now;

      // Determine the live window (default to 180 mins / 3 hours if not set)
      const liveDurationMinutes = vehicle.liveBidDuration || 180;
      const liveWindowMs = liveDurationMinutes * 60 * 1000;

      if (difference <= 0) {
        setDisplayStatus('Sold');
        setIsLive(false);
        return 'Ended';
      }

      // Logic:
      // If time left is less than the live duration, it's LIVE.
      // If time left is more than live duration, it's UPCOMING.
      if (difference <= liveWindowMs) {
         setDisplayStatus('Live Auction');
         setIsLive(true);
      } else {
         setDisplayStatus('Upcoming');
         setIsLive(false);
      }

      const hours = Math.floor((difference / (1000 * 60 * 60)));
      const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((difference % (1000 * 60)) / 1000);

      // Format 00:00:00
      const pad = (n: number) => n.toString().padStart(2, '0');

      // If days exist (> 24h), show days.
      if (hours > 24) {
          const days = Math.floor(hours / 24);
          const remainingHours = hours % 24;
          return `${days}d ${remainingHours}h`;
      }

      return `${hours}h ${pad(minutes)}m ${pad(seconds)}s`;
    };

    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);

    setTimeLeft(calculateTimeLeft());

    return () => clearInterval(timer);
  }, [vehicle.endTime, vehicle.liveBidDuration]);

  return (
    <div 
      className="glass-card rounded-3xl overflow-hidden flex flex-col cursor-pointer h-full transition-all duration-300 hover:-translate-y-2 hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.1)] group"
      onClick={() => onClick(vehicle)}
    >
      <div className="relative h-56 w-full overflow-hidden">
        <img 
          src={`https://picsum.photos/id/${vehicle.imageSeed}/400/300`} 
          alt={`${vehicle.year} ${vehicle.make}`} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-60"></div>
        <div className="absolute top-3 left-3">
           <span className={`px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full text-white shadow-lg backdrop-blur-md border border-white/20 ${isLive ? 'bg-red-600/90 animate-pulse' : 'bg-blue-600/90'}`}>
             {displayStatus}
           </span>
        </div>
        <div className="absolute bottom-3 right-3 bg-white/20 backdrop-blur-md border border-white/30 text-white text-xs font-medium px-3 py-1 rounded-full shadow-lg">
          {vehicle.odometer.toLocaleString()} mi
        </div>
      </div>

      <div className="p-5 flex-1 flex flex-col relative">
        <div className="absolute -top-6 right-4 bg-white rounded-2xl p-2 shadow-lg border border-gray-100">
             <div className="text-[10px] text-gray-400 font-bold uppercase text-center leading-none">BID</div>
             <div className="text-gray-900 font-bold text-lg leading-tight">₹{(vehicle.currentBid/1000).toFixed(1)}k</div>
        </div>

        <h3 className="text-xl font-bold text-gray-800 leading-tight mb-1 group-hover:text-red-600 transition-colors">
          {vehicle.year} {vehicle.make} {vehicle.model}
        </h3>
        <p className="text-xs text-gray-500 mb-4 font-medium tracking-wide">VIN: {vehicle.vin}</p>

        <div className="grid grid-cols-2 gap-y-3 gap-x-2 text-sm mb-5 bg-white/40 rounded-2xl p-3 border border-white/50">
          <div>
            <span className="block text-gray-400 text-[10px] uppercase font-bold">Damage</span>
            <span className="font-semibold text-gray-700 text-xs truncate">{vehicle.primaryDamage}</span>
          </div>
          <div>
            <span className="block text-gray-400 text-[10px] uppercase font-bold">Retail Est.</span>
            <span className="font-semibold text-gray-700 text-xs">₹{vehicle.estRetailValue.toLocaleString()}</span>
          </div>
          <div className="col-span-2">
            <span className="block text-gray-400 text-[10px] uppercase font-bold">Location</span>
            <span className="font-semibold text-gray-700 text-xs truncate">{vehicle.location}</span>
          </div>
        </div>

        <div className="mt-auto">
          <div className="flex justify-between items-center bg-gray-50/50 rounded-full px-4 py-2 border border-white/60">
            <span className="text-gray-500 text-xs font-medium">Ends in</span>
            <span className={`font-mono font-bold text-sm ${isLive ? 'text-red-600' : 'text-gray-700'}`}>
              {timeLeft}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { analyzeVehicleImage } from '../services/geminiService';
import { Vehicle, DamageType, VehicleStatus } from '../types';

interface SellCarProps {
  onNavigate: (page: string) => void;
  onListVehicle?: (vehicle: Vehicle) => void;
}

export const SellCar: React.FC<SellCarProps> = ({ onNavigate, onListVehicle }) => {
  const [step, setStep] = useState(1);
  const [isDragging, setIsDragging] = useState(false);
  const [isValidating, setIsValidating] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);

  // Step 1: Car Image
  const [image, setImage] = useState<string | null>(null);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('image/jpeg');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Step 3: Fine Image
  const [fineImage, setFineImage] = useState<string | null>(null);
  const fineInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    // Step 2 Data
    year: '',
    make: '',
    model: '',
    vin: '',
    odometer: '',
    price: '',
    engine: '',
    topSpeed: '',
    mpg: '',
    description: '',

    // Step 3 Data
    hasFine: 'no',
    isFirstOwner: 'yes',

    // Step 4 Data
    ownerName: '',
    phoneNumber: '',
    streetAddress: '',
    city: '',
    state: '',
    zipCode: '',

    // Step 5 Data
    scheduleType: 'auto', // 'auto' | 'manual'
    auctionDate: '',      // Start Date
    auctionStartTime: '', // Start Time
    auctionEndDate: '',   // End Date
    auctionEndTime: '',   // End Time
    liveBidDuration: '15' // Minutes before end time to start live bidding
  });

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      processFile(files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      processFile(files[0]);
    }
  };

  const processFile = (file: File) => {
    setValidationError(null);
    if (!file.type.startsWith('image/')) {
      setValidationError("Please upload an image file.");
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const result = e.target?.result as string;
      setImage(result);

      const base64Data = result.split(',')[1];
      setImageBase64(base64Data);
      setImageMime(file.type);

      analyzeImage(base64Data, file.type);
    };
    reader.readAsDataURL(file);
  };

  const handleFineImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
        const file = files[0];
        const reader = new FileReader();
        reader.onload = (e) => {
            setFineImage(e.target?.result as string);
        };
        reader.readAsDataURL(file);
    }
  };

  const analyzeImage = async (base64: string, mime: string) => {
    setIsValidating(true);
    try {
      const analysis = await analyzeVehicleImage(base64, mime);

      if (!analysis.isVehicle) {
        setValidationError("Our AI did not detect a car in this image. Please upload a clear picture of a vehicle.");
        setImage(null);
        setImageBase64(null);
      } else {
        setValidationError(null);
        setFormData(prev => ({
            ...prev,
            make: analysis.make || prev.make,
            model: analysis.model || prev.model,
            year: analysis.year || prev.year,
            engine: analysis.engine || prev.engine,
            topSpeed: analysis.topSpeed || prev.topSpeed,
            mpg: analysis.mpg || prev.mpg,
        }));
      }
    } catch (err) {
      console.error(err);
      setValidationError("Could not validate image. Please try again.");
    } finally {
      setIsValidating(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    let endTimeValue: number;
    let liveDuration: number = parseInt(formData.liveBidDuration) || 15;

    if (formData.scheduleType === 'manual') {
        const start = new Date(`${formData.auctionDate}T${formData.auctionStartTime}`);
        const end = new Date(`${formData.auctionEndDate}T${formData.auctionEndTime}`);

        if (isNaN(start.getTime()) || isNaN(end.getTime())) {
            // Wait for inputs
            return; 
        }

        if (end <= start) {
            alert("Auction end time must be after the start time.");
            return;
        }

        // Validate Live Bid Duration
        const durationMs = liveDuration * 60 * 1000;
        const totalAuctionMs = end.getTime() - start.getTime();

        if (durationMs >= totalAuctionMs) {
            alert("Live bid duration cannot be longer than the total auction duration.");
            return;
        }

        endTimeValue = end.getTime();
    } else {
        // Auto Schedule: Starts now, ends in 24 hours
        endTimeValue = Date.now() + 24 * 60 * 60 * 1000;
    }

    // Construct Vehicle Object
    const newVehicle: Vehicle = {
        id: Date.now().toString(),
        year: parseInt(formData.year) || new Date().getFullYear(),
        make: formData.make || 'Unknown Make',
        model: formData.model || 'Unknown Model',
        vin: formData.vin || 'N/A',
        odometer: parseInt(formData.odometer) || 0,
        primaryDamage: DamageType.NORMAL, // Default for user listings
        secondaryDamage: formData.hasFine === 'yes' ? 'Has Fines' : undefined,
        estRetailValue: parseInt(formData.price) * 1.2 || 0, // Estimate higher than asking
        currentBid: parseInt(formData.price) || 0,
        buyNowPrice: parseInt(formData.price) * 1.5 || undefined,
        location: `${formData.city}, ${formData.state}`,
        imageSeed: Math.floor(Math.random() * 500), // Random image for demo, in real app would upload
        status: VehicleStatus.UPCOMING, // Default status, Card handles display logic
        endTime: endTimeValue,
        liveBidDuration: liveDuration,
        watchCount: 0,
        hasKeys: true, // Default
        engine: formData.engine || 'N/A',
        transmission: 'Automatic', // Default
        drive: 'FWD', // Default
        topSpeed: formData.topSpeed,
        mpg: formData.mpg,
        description: formData.description
    };

    if (onListVehicle) {
        onListVehicle(newVehicle);
    }

    // Simulate submission
    setTimeout(() => {
        setStep(6); // Success state
    }, 1000);
  };

  // Progress Bar Width Calculation
  const getProgressWidth = () => {
      switch(step) {
          case 1: return '20%';
          case 2: return '40%';
          case 3: return '60%';
          case 4: return '80%';
          case 5: return '100%';
          default: return '100%';
      }
  };

  // Calculate Duration for display
  const getDurationDisplay = () => {
      if (!formData.auctionDate || !formData.auctionStartTime || !formData.auctionEndDate || !formData.auctionEndTime) return 'Select start and end times';

      const start = new Date(`${formData.auctionDate}T${formData.auctionStartTime}`);
      const end = new Date(`${formData.auctionEndDate}T${formData.auctionEndTime}`);

      if (isNaN(start.getTime()) || isNaN(end.getTime())) return 'Invalid date';

      const diffMs = end.getTime() - start.getTime();
      if (diffMs <= 0) return 'End time must be after start time';

      const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
      const hours = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));

      let durationStr = '';
      if (days > 0) durationStr += `${days} Days `;
      if (hours > 0) durationStr += `${hours} Hours `;
      if (minutes > 0) durationStr += `${minutes} Mins`;

      return durationStr || '0 Mins';
  };

  const getLiveBidStartTime = () => {
    if (!formData.auctionEndDate || !formData.auctionEndTime) return null;
    const end = new Date(`${formData.auctionEndDate}T${formData.auctionEndTime}`);
    if (isNaN(end.getTime())) return null;

    const liveDurationMinutes = parseInt(formData.liveBidDuration);
    const liveStart = new Date(end.getTime() - liveDurationMinutes * 60000);

    return liveStart;
  }

  // Generate 30-minute time slots for the dropdown
  const generateTimeSlots = () => {
    const slots = [];
    for (let i = 0; i < 24; i++) {
      for (let j = 0; j < 60; j += 30) {
        const hour = i.toString().padStart(2, '0');
        const minute = j.toString().padStart(2, '0');
        const timeValue = `${hour}:${minute}`;

        const ampm = i >= 12 ? 'PM' : 'AM';
        const displayHour = i % 12 || 12;
        const displayTime = `${displayHour}:${minute} ${ampm}`;

        slots.push({ value: timeValue, label: displayTime });
      }
    }
    return slots;
  };

  const timeSlots = generateTimeSlots();
  const today = new Date().toISOString().split('T')[0];

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <div className="glass-panel p-8 rounded-[2.5rem] relative overflow-hidden">

        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-2 bg-gray-100">
           <div 
             className="h-full bg-gradient-to-r from-red-600 to-orange-500 transition-all duration-500"
             style={{ width: getProgressWidth() }}
           ></div>
        </div>

        {/* STEP 1: Upload */}
        {step === 1 && (
          <div className="mt-6 animate-fade-in-up">
            <h2 className="text-3xl font-bold text-gray-900 mb-2">Sell Your Vehicle</h2>
            <p className="text-gray-500 mb-8">Step 1 of 5: Upload a photo. Our AI will identify your vehicle.</p>

            <div 
              className={`border-4 border-dashed rounded-[2rem] p-12 text-center transition-all cursor-pointer relative overflow-hidden ${
