export enum DamageType {
  COLLISION = 'Collision',
  FLOOD = 'Flood',
  THEFT = 'Theft Recovery',
  HAIL = 'Hail',
  NORMAL = 'Normal Wear',
  MECHANICAL = 'Mechanical',
}

export enum VehicleStatus {
  UPCOMING = 'Upcoming',
  LIVE = 'Live Auction',
  SOLD = 'Sold',
}

export interface User {
  id: string;
  username: string;
  fullName: string;
  avatarUrl: string;
  followers: number;
  following: number;
  bio: string;
  isVerified?: boolean;
}

export interface Vehicle {
  id: string;
  ownerId?: string; // Link to a User
  year: number;
  make: string;
  model: string;
  vin: string;
  odometer: number;
  primaryDamage: DamageType;
  secondaryDamage?: string;
  estRetailValue: number;
  currentBid: number;
  buyNowPrice?: number;
  location: string;
  imageSeed: number; 
  status: VehicleStatus;
  endTime: number; 
  watchCount: number;
  hasKeys: boolean;
  engine: string;
  transmission: string;
  drive: string;
  topSpeed?: string;
  mpg?: string;
  description?: string;
  liveBidDuration?: number;

  // User specific fields (contextual to the viewer)
  isOwner?: boolean; // If true, viewer owns this
  isWatchlisted?: boolean;
  userBidStatus?: 'none' | 'winning' | 'outbid' | 'won' | 'lost';
}

export interface Bid {
  vehicleId: string;
  amount: number;
  timestamp: number;
}

import React, { useState } from 'react';
import { User } from '../types';
import { MOCK_USERS } from '../constants';

interface NavbarProps {
  onNavigate: (page: string) => void;
  activePage: string;
  onSearchUser: (user: User) => void;
}

export const Navbar: React.FC<NavbarProps> = ({ onNavigate, activePage, onSearchUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showResults, setShowResults] = useState(false);

  const filteredUsers = searchTerm 
    ? MOCK_USERS.filter(u => u.username.toLowerCase().includes(searchTerm.toLowerCase()) || u.fullName.toLowerCase().includes(searchTerm.toLowerCase()))
    : [];

  const handleUserSelect = (user: User) => {
      onSearchUser(user);
      setSearchTerm('');
      setShowResults(false);
  };

  return (
    <nav className="sticky top-0 z-50 px-4 py-3">
      <div className="max-w-7xl mx-auto glass-panel rounded-2xl px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="flex items-center cursor-pointer group" onClick={() => onNavigate('home')}>
            <span className="text-2xl font-bold tracking-tighter italic text-gray-800 group-hover:scale-105 transition-transform">
              Auto<span className="bg-gradient-to-r from-red-600 to-orange-500 bg-clip-text text-transparent">Bid</span>
            </span>
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:block">
            <div className="ml-10 flex items-baseline space-x-2">
              <button
                onClick={() => onNavigate('home')}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'home' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                Auctions
              </button>
              <button
                onClick={() => onNavigate('profile')}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'profile' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                Profile
              </button>
              <button 
                onClick={() => onNavigate('sell')}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'sell' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                Sell Vehicle
              </button>
            </div>
          </div>

          {/* User Search & Actions */}
          <div className="flex items-center gap-4 relative">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Search Users..." 
                value={searchTerm}
                onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setShowResults(true);
                }}
                onBlur={() => setTimeout(() => setShowResults(false), 200)}
                className="bg-gray-100/50 border border-white/50 text-gray-700 placeholder-gray-400 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-red-200 focus:bg-white transition-all text-sm w-48 lg:w-64 shadow-inner"
              />
              {showResults && searchTerm && (
                  <div className="absolute top-full left-0 w-full mt-2 bg-white/90 backdrop-blur-xl rounded-2xl shadow-xl border border-white/50 overflow-hidden py-2">
                      {filteredUsers.length > 0 ? (
                          filteredUsers.map(user => (
                              <div 
                                key={user.id} 
                                onClick={() => handleUserSelect(user)}
                                className="px-4 py-3 hover:bg-red-50 cursor-pointer flex items-center gap-3 transition-colors"
                              >
                                  <img src={user.avatarUrl} alt={user.username} className="w-8 h-8 rounded-full border border-gray-200" />
                                  <div>
                                      <p className="text-sm font-bold text-gray-900 leading-none">{user.username}</p>
                                      <p className="text-xs text-gray-500">{user.fullName}</p>
                                  </div>
                              </div>
                          ))
                      ) : (
                          <div className="px-4 py-3 text-sm text-gray-500">No users found</div>
                      )}
                  </div>
              )}
            </div>

            {/* User Avatar / Profile Link */}
            <button 
                onClick={() => onNavigate('profile')}
                className="w-10 h-10 rounded-full bg-gradient-to-br from-red-600 to-orange-500 p-0.5 shadow-lg hover:scale-105 transition-transform"
            >
                <img 
                    src="https://i.pravatar.cc/150?u=me" 
                    alt="Profile" 
                    className="w-full h-full rounded-full border-2 border-white"
                />
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

