        )}

        {currentView === 'detail' && (
           isLoading ? (
             <VehicleDetailSkeleton />
           ) : (
             selectedVehicle && (
                <VehicleDetail 
                  vehicle={selectedVehicle} 
                  onBack={handleBackToHome}
                  onPlaceBid={handlePlaceBid}
                />
             )
           )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'profile' && (
          isLoading ? (
            <DashboardSkeleton />
          ) : (
            <div className="max-w-4xl mx-auto px-4 py-8">
