                        <img 
                            src={profileUser.avatarUrl} 
                            alt={profileUser.username}
                            className="w-32 h-32 rounded-full border-4 border-white shadow-xl"
                        />
                        {profileUser.isVerified && (
                             <div className="absolute bottom-1 right-1 bg-blue-500 text-white p-1 rounded-full border-2 border-white">
                                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                             </div>
                        )}
                    </div>

                    <div className="flex-1 text-center md:text-left">
                        <div className="flex flex-col md:flex-row items-center gap-4 mb-4">
                            <h1 className="text-3xl font-bold text-gray-900">{profileUser.username}</h1>
                            {!isViewingSelf && (
                                <button className="bg-blue-500 text-white px-6 py-1.5 rounded-xl font-bold shadow-lg shadow-blue-500/30 hover:scale-105 transition-transform text-sm">
                                    Follow
                                </button>
                            )}
                            {isViewingSelf && (
                                <button className="bg-gray-100 text-gray-700 px-4 py-1.5 rounded-xl font-bold hover:bg-gray-200 transition-colors text-sm">
                                    Edit Profile
                                </button>
                            )}
                        </div>

                        <div className="flex justify-center md:justify-start gap-8 mb-5">
                            <div className="text-center md:text-left">
                                <span className="font-bold text-lg block text-gray-900">{profileListings.length}</span>
                                <span className="text-gray-500 text-sm">Auctions</span>
                            </div>
                            <div className="text-center md:text-left">
                                <span className="font-bold text-lg block text-gray-900">{profileUser.followers}</span>
                                <span className="text-gray-500 text-sm">Followers</span>
                            </div>
                            <div className="text-center md:text-left">
                                <span className="font-bold text-lg block text-gray-900">{profileUser.following}</span>
                                <span className="text-gray-500 text-sm">Following</span>
                            </div>
                        </div>

                        <div className="space-y-1">
                            <p className="font-bold text-gray-900">{profileUser.fullName}</p>
                            <p className="text-gray-600 text-sm leading-relaxed max-w-md">{profileUser.bio}</p>
                        </div>
                    </div>
                </div>

                {/* Tabs */}
                <div className="glass-panel rounded-[2rem] overflow-hidden min-h-[500px]">
                    <div className="flex border-b border-gray-200/50 justify-center">
                        <button 
                            onClick={() => setProfileTab('auctions')}
                            className={`flex-1 py-4 text-xs sm:text-sm font-bold uppercase tracking-wider transition-all border-b-2 ${profileTab === 'auctions' ? 'border-gray-900 text-gray-900' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
                        >
                            <span className="hidden sm:inline">Vehicle</span> Auctions
                        </button>
                        {isViewingSelf && (
                            <>
                                <button 
                                    onClick={() => setProfileTab('watchlist')}
                                    className={`flex-1 py-4 text-xs sm:text-sm font-bold uppercase tracking-wider transition-all border-b-2 ${profileTab === 'watchlist' ? 'border-blue-500 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
                                >
                                    Watchlist
