                                <button 
                                    onClick={() => setProfileTab('won')}
                                    className={`flex-1 py-4 text-xs sm:text-sm font-bold uppercase tracking-wider transition-all border-b-2 ${profileTab === 'won' ? 'border-green-500 text-green-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
