            <div className="mt-8 flex items-center justify-center gap-4">
              <div className="h-px bg-gray-300 w-full opacity-50"></div>
              <span className="text-gray-400 text-sm font-medium whitespace-nowrap">Or continue with</span>
              <div className="h-px bg-gray-300 w-full opacity-50"></div>
            </div>

            <button
              type="button"
              onClick={handleGoogleLogin}
              disabled={isLoading}
              className="mt-6 w-full bg-white border border-gray-200 text-gray-700 font-bold py-4 rounded-2xl hover:bg-gray-50 hover:border-gray-300 transition-all shadow-sm flex items-center justify-center gap-3 group"
            >
              <svg className="w-5 h-5 transition-transform group-hover:scale-110" viewBox="0 0 24 24">
                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.26.81-.58z" fill="#FBBC05" />
                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
              </svg>
              {mode === 'login' ? 'Sign in with Google' : 'Sign up with Google'}
            </button>

            <div className="mt-8 text-center">
                <p className="text-gray-600 font-medium">
                    {mode === 'login' ? "Don't have an account? " : "Already have an account? "}
                    <button 
                        onClick={() => {
                          setMode(mode === 'login' ? 'register' : 'login');
                          setConfirmPassword('');
                          setPassword('');
                          setUsername('');
                        }}
                        className="font-bold text-red-600 hover:text-red-700 hover:underline transition-all ml-1"
                    >
                        {mode === 'login' ? 'Sign Up' : 'Log In'}
                    </button>
                </p>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User } from '../types';
import { MOCK_USERS } from '../constants';

interface NavbarProps {
  onNavigate: (page: string) => void;
  activePage: string;
  onSearchUser: (user: User) => void;
  currentUser?: User;
}

export const Navbar: React.FC<NavbarProps> = ({ onNavigate, activePage, onSearchUser, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showResults, setShowResults] = useState(false);

  const filteredUsers = searchTerm 
    ? MOCK_USERS.filter(u => u.username.toLowerCase().includes(searchTerm.toLowerCase()) || u.fullName.toLowerCase().includes(searchTerm.toLowerCase()))
    : [];

  const handleUserSelect = (user: User) => {
      onSearchUser(user);
      setSearchTerm('');
      setShowResults(false);
  };

  return (
    <nav className="sticky top-0 z-50 px-4 py-3">
      <div className="max-w-7xl mx-auto glass-panel rounded-2xl px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <div className="flex items-center cursor-pointer group" onClick={() => onNavigate('home')}>
            <span className="text-2xl font-bold tracking-tighter italic text-gray-800 group-hover:scale-105 transition-transform">
              Auto<span className="bg-gradient-to-r from-red-600 to-orange-500 bg-clip-text text-transparent">Bid</span>
            </span>
          </div>

          {/* Desktop Menu */}
          <div className="hidden md:block">
            <div className="ml-10 flex items-baseline space-x-2">
              <button
                onClick={() => onNavigate('home')}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'home' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                Auctions
              </button>
              <button
                onClick={() => onNavigate('profile')}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'profile' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                Profile
              </button>
              <button 
                onClick={() => onNavigate('sell')}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'sell' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                Sell Vehicle
              </button>
            </div>
          </div>

          {/* User Search & Actions */}
          <div className="flex items-center gap-4 relative">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Search Users..." 
                value={searchTerm}
                onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setShowResults(true);
                }}
                onBlur={() => setTimeout(() => setShowResults(false), 200)}
                className="bg-gray-100/50 border border-white/50 text-gray-700 placeholder-gray-400 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-red-200 focus:bg-white transition-all text-sm w-48 lg:w-64 shadow-inner"
              />
              {showResults && searchTerm && (
                  <div className="absolute top-full left-0 w-full mt-2 bg-white/90 backdrop-blur-xl rounded-2xl shadow-xl border border-white/50 overflow-hidden py-2">
                      {filteredUsers.length > 0 ? (
                          filteredUsers.map(user => (
                              <div 
                                key={user.id} 
                                onClick={() => handleUserSelect(user)}
                                className="px-4 py-3 hover:bg-red-50 cursor-pointer flex items-center gap-3 transition-colors"
                              >
                                  <img src={user.avatarUrl} alt={user.username} className="w-8 h-8 rounded-full border border-gray-200" />
                                  <div>
                                      <p className="text-sm font-bold text-gray-900 leading-none">{user.username}</p>
                                      <p className="text-xs text-gray-500">{user.fullName}</p>
                                  </div>
                              </div>
                          ))
                      ) : (
                          <div className="px-4 py-3 text-sm text-gray-500">No users found</div>
                      )}
                  </div>
              )}
            </div>

            {/* User Avatar / Profile Link */}
            <button 
                onClick={() => onNavigate('profile')}
                className="w-10 h-10 rounded-full bg-gradient-to-br from-red-600 to-orange-500 p-0.5 shadow-lg hover:scale-105 transition-transform"
            >
                <img 
                    src={currentUser?.avatarUrl || "https://i.pravatar.cc/150?u=me"} 
                    alt="Profile" 
                    className="w-full h-full rounded-full border-2 border-white"
                />
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle, User } from './types';
import { MOCK_VEHICLES, CURRENT_USER, MOCK_USERS } from './constants';

type ViewState = 'home' | 'detail' | 'profile' | 'auth' | 'sell';
type AuctionFilter = 'all' | 'live' | 'upcoming';
type ProfileTab = 'auctions' | 'watchlist' | 'won' | 'lost';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // User State
  const [currentUser, setCurrentUser] = useState<User>(CURRENT_USER);

  // Profile State
  const [profileUser, setProfileUser] = useState<User>(CURRENT_USER); // User currently being viewed
  const [profileTab, setProfileTab] = useState<ProfileTab>('auctions');

  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Initial load simulation
  useEffect(() => {
    // If we were real, we'd check session here.
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = (userData?: { username: string }) => {
      setIsAuthenticated(true);
      if (userData?.username) {
          const newUser: User = {
              ...CURRENT_USER,
              id: `user-${Date.now()}`,
              username: userData.username,
              fullName: userData.username, // Default fallback
              avatarUrl: `https://i.pravatar.cc/150?u=${userData.username}`,
              isVerified: false,
              followers: 0,
              following: 0,
              bio: 'New member at AutoBid.'
          };
          setCurrentUser(newUser);
          setProfileUser(newUser);
      }
      setCurrentView('home');
  };

  const navigate = (view: string) => {
    if (view === 'profile') {
        // Default to current user when clicking "Profile" in nav
        setProfileUser(currentUser);
    }
    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { 
          ...v, 
          currentBid: amount,
          userBidStatus: 'winning' // Optimistically update status
      } : v
    );
    setVehicles(updatedVehicles);

    setSelectedVehicle({ ...selectedVehicle, currentBid: amount, userBidStatus: 'winning' });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  const handleListVehicle = (newVehicle: Vehicle) => {
      // Add new vehicle with ownerId of current user
      const vehicleWithOwner = { ...newVehicle, ownerId: currentUser.id };
      setVehicles(prev => [vehicleWithOwner, ...prev]);
  };

  const handleUserSearch = (user: User) => {
      setProfileUser(user);
      setProfileTab('auctions'); // Reset tab to default when viewing a new user
      navigate('profile');
  };

  // Filter Logic for Home View
  const filteredVehicles = vehicles.filter(v => {
    // Hide sold vehicles from main feed
    if (v.status === 'Sold' || v.status === 'Sold' as any) return false; 

    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    const now = Date.now();
    const liveDurationMinutes = v.liveBidDuration || 180;
    const liveWindowMs = liveDurationMinutes * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        return timeLeft > 0 && timeLeft <= liveWindowMs;
    }
    if (auctionFilter === 'upcoming') {
        return timeLeft > liveWindowMs;
    }

    return timeLeft > 0;
  });

  // Profile Data Filtering
  const isViewingSelf = profileUser.id === currentUser.id;

  const profileListings = vehicles.filter(v => v.ownerId === profileUser.id || (isViewingSelf && v.isOwner));
  const profileWatchlist = isViewingSelf ? vehicles.filter(v => v.isWatchlisted) : [];
  const profileWon = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'won') : [];
  const profileLost = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'lost') : [];

  // Determine which tab to show vehicles for
  let activeProfileVehicles: Vehicle[] = [];
  if (profileTab === 'auctions') activeProfileVehicles = profileListings;
  else if (profileTab === 'watchlist') activeProfileVehicles = profileWatchlist;
  else if (profileTab === 'won') activeProfileVehicles = profileWon;
  else if (profileTab === 'lost') activeProfileVehicles = profileLost;


  // Force Authentication
  if (!isAuthenticated) {
      return (
          <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4">
              <Auth initialMode="login" onLoginSuccess={handleLoginSuccess} />
          </div>
      );
  }

  return (
    <div className="min-h-screen font-sans text-gray-900 pb-28 md:pb-32 bg-transparent selection:bg-red-200 selection:text-red-900">
      <Navbar onNavigate={navigate} activePage={currentView} onSearchUser={handleUserSearch} currentUser={currentUser} />

      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder="Find your next ride..." 
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setAuctionFilter('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'all' ? 'bg-gradient-to-r from-gray-800 to-gray-700 text-white shadow-gray-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-gray-900'}`}
                >
                  All Auctions
                </button>
                <button 
                  onClick={() => setAuctionFilter('live')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'live' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  <span className={`inline-block w-2 h-2 rounded-full mr-2 ${auctionFilter === 'live' ? 'bg-white animate-pulse' : 'bg-red-500'}`}></span>
                  Live Auctions
                </button>
                <button 
                  onClick={() => setAuctionFilter('upcoming')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'upcoming' ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-blue-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-blue-500'}`}
                >
                  Upcoming
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">
                   {auctionFilter === 'all' && 'Vehicle Inventory'}
                   {auctionFilter === 'live' && 'Live Auctions'}
                   {auctionFilter === 'upcoming' && 'Upcoming Auctions'}
                   <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span>
               </h2>
               <div className="hidden sm:block text-sm text-gray-600 bg-white/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/40">Sort by: <span className="font-bold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {isLoading ? (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                 {[...Array(8)].map((_, i) => <VehicleCardSkeleton key={i} />)}
               </div>
            ) : filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 glass-panel rounded-[2rem]">
                <h3 className="text-xl font-bold text-gray-900">No vehicles found</h3>
                <p className="text-gray-500 mt-2">
                    {auctionFilter === 'live' ? "No auctions are ending in the next 3 hours." : "Try adjusting your search terms or filters."}
                </p>
              </div>
            )}
          </div>
        )}

        {currentView === 'detail' && (
           isLoading ? (
             <VehicleDetailSkeleton />
           ) : (
             selectedVehicle && (
                <VehicleDetail 
                  vehicle={selectedVehicle} 
                  onBack={handleBackToHome}
                  onPlaceBid={handlePlaceBid}
                />
             )
           )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'profile' && (
          isLoading ? (
            <div className="max-w-3xl mx-auto px-4 py-8 animate-pulse">
               <div className="flex gap-8 items-center mb-8">
                   <div className="w-32 h-32 rounded-full bg-gray-200"></div>
                   <div className="flex-1 space-y-4">
                       <div className="h-8 w-48 bg-gray-200 rounded"></div>
                       <div className="h-4 w-3/4 bg-gray-200 rounded"></div>
                   </div>
               </div>
               <div className="grid grid-cols-3 gap-1">
                   {[1,2,3,4,5,6].map(i => <div key={i} className="aspect-square bg-gray-200"></div>)}
               </div>
            </div>
          ) : (
            <div className="max-w-3xl mx-auto px-4 py-4 md:py-8">
                {/* Instagram-style Header */}
                <div className="mb-8">
                    <div className="flex flex-col md:flex-row gap-6 md:gap-12 items-center md:items-start">
                        {/* Avatar */}
                        <div className="flex-shrink-0">
                            <div className="relative">
                                <img 
                                    src={profileUser.avatarUrl} 
                                    alt={profileUser.username}
                                    className="w-24 h-24 md:w-36 md:h-36 rounded-full border-2 border-gray-200 p-1 object-cover"
                                />
                                {profileUser.isVerified && (
                                     <div className="absolute bottom-1 right-1 bg-blue-500 text-white p-1 rounded-full border-2 border-white">
                                        <svg className="w-3 h-3 md:w-4 md:h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                     </div>
                                )}
                            </div>
                        </div>

                        {/* Info Section */}
                        <div className="flex-1 w-full md:w-auto">
                            <div className="flex flex-col md:flex-row items-center md:items-start gap-4 mb-4">
                                <h1 className="text-xl md:text-2xl font-light text-gray-800">{profileUser.username}</h1>
                                <div className="flex gap-2">
                                     {!isViewingSelf ? (
                                        <>
                                            <button className="bg-blue-500 text-white px-6 py-1.5 rounded-lg font-semibold text-sm hover:bg-blue-600 transition-colors">
                                                Follow
                                            </button>
                                            <button className="bg-gray-100 text-gray-800 px-4 py-1.5 rounded-lg font-semibold text-sm hover:bg-gray-200 transition-colors">
                                                Message
                                            </button>
                                        </>
                                    ) : (
                                        <button className="bg-gray-100 text-gray-800 px-4 py-1.5 rounded-lg font-semibold text-sm hover:bg-gray-200 transition-colors">
                                            Edit Profile
                                        </button>
                                    )}
                                </div>
                            </div>

                            {/* Stats */}
                            <div className="flex justify-around md:justify-start gap-8 md:gap-10 mb-4 border-t border-b md:border-none border-gray-100 py-3 md:py-0">
                                <div className="text-center md:text-left">
                                    <span className="font-semibold text-gray-900 block md:inline mr-1">{profileListings.length}</span>
                                    <span className="text-gray-500 text-sm">auctions</span>
                                </div>
                                <div className="text-center md:text-left">
                                    <span className="font-semibold text-gray-900 block md:inline mr-1">{profileUser.followers}</span>
                                    <span className="text-gray-500 text-sm">followers</span>
                                </div>
                                <div className="text-center md:text-left">
                                    <span className="font-semibold text-gray-900 block md:inline mr-1">{profileUser.following}</span>
                                    <span className="text-gray-500 text-sm">following</span>
                                </div>
                            </div>

                            {/* Bio (Desktop) */}
                            <div className="hidden md:block">
                                <p className="font-semibold text-gray-900 text-sm">{profileUser.fullName}</p>
                                <p className="text-gray-600 text-sm whitespace-pre-line">{profileUser.bio}</p>
                            </div>
                        </div>
                    </div>

                    {/* Bio (Mobile) */}
                    <div className="md:hidden px-2 mt-2">
                        <p className="font-semibold text-gray-900 text-sm">{profileUser.fullName}</p>
                        <p className="text-gray-600 text-sm whitespace-pre-line">{profileUser.bio}</p>
                    </div>
                </div>

                {/* Tabs - Instagram Style */}
                <div className="border-t border-gray-200">
                    <div className="flex justify-center gap-12">
                         <button 
                            onClick={() => setProfileTab('auctions')}
                            className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'auctions' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                        >
                            <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
                            Auctions
                        </button>
                        {isViewingSelf && (
                            <>
                                <button 
                                    onClick={() => setProfileTab('watchlist')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'watchlist' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                     <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                                    Saved
                                </button>
                                <button 
                                    onClick={() => setProfileTab('won')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'won' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                    Won
                                </button>
                                <button 
                                    onClick={() => setProfileTab('lost')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'lost' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
