interface SettingsProps {
  onNavigate: (page: string) => void;
  onLogout: () => void;
  currentUser: User;
}

export const Settings: React.FC<SettingsProps> = ({ onNavigate, onLogout, currentUser }) => {
  const [isPrivate, setIsPrivate] = useState(false);

  const handleDownload = (format: 'json' | 'html') => {
    const data = {
      user: currentUser,
      timestamp: new Date().toISOString(),
      app: "AutoBid AI",
      status: "Exported Data"
    };

    let content = '';
    let mimeType = '';
    let extension = '';

    if (format === 'json') {
      content = JSON.stringify(data, null, 2);
      mimeType = 'application/json';
      extension = 'json';
    } else {
      content = `
        <html>
          <head><title>User Data Export</title></head>
          <body>
            <h1>${currentUser.username}</h1>
            <p>Full Name: ${currentUser.fullName}</p>
            <p>ID: ${currentUser.id}</p>
            <p>Export Date: ${new Date().toLocaleDateString()}</p>
          </body>
        </html>
      `;
      mimeType = 'text/html';
      extension = 'html';
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `autobid_data_${currentUser.username}.${extension}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const SectionHeader: React.FC<{ title: string; icon: React.ReactNode }> = ({ title, icon }) => (
    <div className="flex items-center gap-2 px-4 py-3 text-sm font-bold text-gray-500 uppercase tracking-wider mt-4">
      {icon}
