      <span className="font-medium text-sm sm:text-base">{label}</span>
      {rightElement || (
        <svg className="w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
        </svg>
      )}
    </div>
  );

  return (
    <div className="max-w-2xl mx-auto px-4 py-8 pb-32">
      <div className="flex items-center mb-6">
        <button 
            onClick={() => onNavigate('profile')}
            className="p-2 rounded-full hover:bg-gray-200 transition-colors mr-2"
        >
            <svg className="w-6 h-6 text-gray-700" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
        </button>
        <h1 className="text-2xl font-bold text-gray-900">Settings</h1>
      </div>

      <div className="glass-panel rounded-[2rem] overflow-hidden shadow-sm">

        {/* Account Details */}
        <SectionHeader 
            title="Account Details" 
            icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>} 
        />
        <div className="flex flex-col">
            <div className="flex items-center justify-between px-6 py-4 bg-white/60 border-b border-gray-100">
                <span className="font-medium text-gray-800 text-sm sm:text-base">Private Account</span>
                <div 
                    onClick={() => setIsPrivate(!isPrivate)}
                    className={`w-12 h-7 rounded-full p-1 cursor-pointer transition-colors duration-300 ${isPrivate ? 'bg-red-500' : 'bg-gray-300'}`}
                >
                    <div className={`bg-white w-5 h-5 rounded-full shadow-md transform transition-transform duration-300 ${isPrivate ? 'translate-x-5' : 'translate-x-0'}`}></div>
                </div>
            </div>
            <MenuItem label="Blocked Users" />
            <MenuItem label="Languages" rightElement={<span className="text-gray-500 text-sm mr-2">English (US)</span>} />
            <MenuItem label="Verify Account" rightElement={currentUser.isVerified ? <span className="text-blue-500 font-bold text-xs bg-blue-50 px-2 py-1 rounded-full">Verified</span> : undefined} />
        </div>

        {/* Help and Support */}
        <SectionHeader 
            title="Help & Support" 
            icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 5.636l-3.536 3.536m0 5.656l3.536 3.536M9.172 9.172L5.636 5.636m3.536 9.192l-3.536 3.536M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-5 0a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} 
