interface SettingsProps {
  onNavigate: (page: string) => void;
  onLogout: () => void;
  currentUser: User;
}

type SettingsSection = 
  | 'MENU' 
  | 'BLOCKED_USERS' 
  | 'LANGUAGES' 
  | 'VERIFY' 
  | 'AI_ASSISTANT' 
  | 'RAISE_TICKET' 
  | 'VIEW_TICKETS' 
  | 'CONTACT_SUPPORT' 
  | 'CHANGE_PASSWORD' 
  | 'DEVICES'
  | 'ADD_ACCOUNT'
  | 'SWITCH_ACCOUNT';

export const Settings: React.FC<SettingsProps> = ({ onNavigate, onLogout, currentUser }) => {
  const [activeSection, setActiveSection] = useState<SettingsSection>('MENU');

  // -- State for Account Details --
  const [isPrivate, setIsPrivate] = useState(false);
  const [blockedUsers, setBlockedUsers] = useState([
    { id: 'b1', name: 'spam_bot_99' },
    { id: 'b2', name: 'annoying_bidder' }
  ]);
  const [selectedLanguage, setSelectedLanguage] = useState('English (US)');
  const [isVerificationPending, setIsVerificationPending] = useState(false);

  // -- State for Tickets --
  const [tickets, setTickets] = useState([
    { id: '#1023', subject: 'Payment Issue', status: 'Resolved', date: '2023-10-12' },
    { id: '#1055', subject: 'Bid Not Registering', status: 'Open', date: '2023-11-05' }
  ]);

  // -- Helpers --
  const handleDownload = (format: 'json' | 'html') => {
    const data = {
      user: currentUser,
      timestamp: new Date().toISOString(),
      settings: { isPrivate, language: selectedLanguage },
      app: "AutoBid AI"
    };

    let content = '';
    let mimeType = '';
    let extension = '';

    if (format === 'json') {
      content = JSON.stringify(data, null, 2);
      mimeType = 'application/json';
      extension = 'json';
    } else {
      content = `
        <html>
          <head>
            <title>AutoBid Data Export</title>
            <style>body{font-family:sans-serif;padding:2rem;max-width:600px;margin:0 auto;line-height:1.6}</style>
          </head>
          <body>
            <h1>Data Export for ${currentUser.username}</h1>
            <p><strong>Export Date:</strong> ${new Date().toLocaleDateString()}</p>
            <hr/>
            <h2>Profile</h2>
            <ul>
              <li><strong>ID:</strong> ${currentUser.id}</li>
              <li><strong>Name:</strong> ${currentUser.fullName}</li>
              <li><strong>Verified:</strong> ${currentUser.isVerified ? 'Yes' : 'No'}</li>
            </ul>
            <h2>Settings</h2>
             <ul>
              <li><strong>Privacy:</strong> ${isPrivate ? 'Private' : 'Public'}</li>
              <li><strong>Language:</strong> ${selectedLanguage}</li>
            </ul>
          </body>
        </html>
      `;
      mimeType = 'text/html';
      extension = 'html';
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `autobid_${currentUser.username}_${Date.now()}.${extension}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const SubViewHeader: React.FC<{ title: string }> = ({ title }) => (
    <div className="flex items-center mb-6">
       <button 
            onClick={() => setActiveSection('MENU')}
            className="p-2 -ml-2 rounded-full hover:bg-gray-200 transition-colors mr-2 text-gray-600"
        >
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
        </button>
        <h2 className="text-xl font-bold text-gray-900">{title}</h2>
    </div>
  );

  // --- Sub-Components ---

  const BlockedUsersView = () => (
    <div className="animate-fade-in-right">
      <SubViewHeader title="Blocked Users" />
      <div className="glass-panel rounded-2xl overflow-hidden">
        {blockedUsers.length === 0 ? (
          <div className="p-8 text-center text-gray-500">No blocked users.</div>
        ) : (
          blockedUsers.map(user => (
            <div key={user.id} className="flex items-center justify-between p-4 border-b border-gray-100 last:border-0">
               <span className="font-medium text-gray-800">{user.name}</span>
               <button 
                 onClick={() => setBlockedUsers(blockedUsers.filter(u => u.id !== user.id))}
                 className="text-xs bg-gray-100 hover:bg-red-50 text-gray-600 hover:text-red-600 px-3 py-1.5 rounded-full transition-colors"
               >
                 Unblock
               </button>
            </div>
          ))
        )}
      </div>
    </div>
  );

  const LanguageView = () => {
    const langs = ['English (US)', 'English (UK)', 'Español', 'Français', 'Deutsch', 'Hindi', '日本語'];
    return (
      <div className="animate-fade-in-right">
        <SubViewHeader title="Languages" />
        <div className="glass-panel rounded-2xl overflow-hidden">
          {langs.map(lang => (
            <div 
              key={lang} 
              onClick={() => { setSelectedLanguage(lang); setActiveSection('MENU'); }}
              className="flex items-center justify-between p-4 border-b border-gray-100 last:border-0 cursor-pointer hover:bg-white/50"
            >
              <span className="font-medium text-gray-800">{lang}</span>
              {selectedLanguage === lang && <span className="text-red-600 font-bold">✓</span>}
            </div>
