                className={`px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${activePage === 'sell' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-gray-600 hover:bg-white/50 hover:text-red-500'}`}
              >
                {t.sell}
              </button>
            </div>
          </div>

          {/* User Search & Actions */}
          <div className="flex items-center gap-4 relative">
            <div className="relative">
              <input 
                type="text" 
                placeholder={t.searchPlaceholder} 
                value={searchTerm}
                onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setShowResults(true);
                }}
                onBlur={() => setTimeout(() => setShowResults(false), 200)}
                className="bg-gray-100/50 border border-white/50 text-gray-700 placeholder-gray-400 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-red-200 focus:bg-white transition-all text-sm w-48 lg:w-64 shadow-inner"
              />
              {showResults && searchTerm && (
                  <div className="absolute top-full left-0 w-full mt-2 bg-white/90 backdrop-blur-xl rounded-2xl shadow-xl border border-white/50 overflow-hidden py-2">
                      {filteredUsers.length > 0 ? (
                          filteredUsers.map(user => (
                              <div 
                                key={user.id} 
                                onClick={() => handleUserSelect(user)}
                                className="px-4 py-3 hover:bg-red-50 cursor-pointer flex items-center gap-3 transition-colors"
                              >
                                  <img src={user.avatarUrl} alt={user.username} className="w-8 h-8 rounded-full border border-gray-200" />
                                  <div>
                                      <p className="text-sm font-bold text-gray-900 leading-none">{user.username}</p>
                                      <p className="text-xs text-gray-500">{user.fullName}</p>
                                  </div>
                              </div>
                          ))
                      ) : (
                          <div className="px-4 py-3 text-sm text-gray-500">No users found</div>
                      )}
                  </div>
              )}
            </div>

            {/* User Avatar / Profile Link */}
            <button 
                onClick={() => onNavigate('profile')}
                className="w-10 h-10 rounded-full bg-gradient-to-br from-red-600 to-orange-500 p-0.5 shadow-lg hover:scale-105 transition-transform"
            >
                <img 
                    src={currentUser?.avatarUrl || "https://i.pravatar.cc/150?u=me"} 
                    alt="Profile" 
                    className="w-full h-full rounded-full border-2 border-white"
                />
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

