      alert("Add Account feature would open a new login flow.");
  };

  const handleSwitchAccount = () => {
      alert("Switch Account would show a list of saved accounts.");
  };

  if (activeSection !== 'MENU') {
      return (
          <div className="max-w-2xl mx-auto px-4 py-8 pb-32 min-h-screen">
              {activeSection === 'BLOCKED_USERS' && <BlockedUsersView />}
              {activeSection === 'LANGUAGES' && <LanguageView />}
              {activeSection === 'VERIFY' && <VerifyView />}
              {activeSection === 'AI_ASSISTANT' && <AIAssistantView />}
              {activeSection === 'RAISE_TICKET' && <RaiseTicketView />}
              {activeSection === 'VIEW_TICKETS' && <ViewTicketsView />}
              {activeSection === 'CONTACT_SUPPORT' && <ContactSupportView />}
              {activeSection === 'CHANGE_PASSWORD' && <ChangePasswordView />}
              {activeSection === 'DEVICES' && <DevicesView />}
          </div>
      );
  }

  return (
    <div className="max-w-2xl mx-auto px-4 py-8 pb-32 animate-fade-in-up relative">

      {/* Confirmation Modal */}
      {showDownloadConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setShowDownloadConfirm(false)}></div>
          <div className="relative bg-white rounded-2xl p-6 max-w-sm w-full shadow-2xl animate-fade-in-up">
            <h3 className="text-xl font-bold text-gray-900 mb-2">Download Data</h3>
            <div className="bg-red-50 border border-red-100 p-3 rounded-lg mb-4">
              <p className="text-red-700 text-xs font-bold uppercase mb-1">Warning</p>
              <p className="text-red-600 text-sm">This file contains sensitive personal information including your bid history, searches, and account details. Do not share this file with unauthorized third parties.</p>
            </div>
            <p className="text-gray-600 text-sm mb-6">Are you sure you want to download your complete account history?</p>
            <div className="flex gap-3">
              <button 
                onClick={() => setShowDownloadConfirm(false)}
                className="flex-1 py-2.5 rounded-xl border border-gray-200 font-bold text-gray-600 hover:bg-gray-50"
              >
                Cancel
              </button>
              <button 
                onClick={executeDownload}
                className="flex-1 py-2.5 rounded-xl bg-red-600 text-white font-bold hover:bg-red-700 shadow-lg shadow-red-500/30"
              >
                Confirm Download
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center mb-6">
        <button 
            onClick={() => onNavigate('profile')}
            className="p-2 rounded-full hover:bg-gray-200 transition-colors mr-2 text-gray-600"
