        </button>
        <h1 className="text-2xl font-bold text-gray-900">Settings</h1>
      </div>

      <div className="glass-panel rounded-[2rem] overflow-hidden shadow-sm">

        {/* Account Details */}
        <SectionHeader 
            title="Account Details" 
            icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>} 
        />
        <div className="flex flex-col">
            <div className="px-6 py-4 bg-white/60 border-b border-gray-100">
                <span className="block font-medium text-gray-800 text-sm sm:text-base mb-2">Private Account</span>
                <div className="flex gap-4">
                    <label className="flex items-center gap-2 cursor-pointer">
                        <input 
                            type="radio" 
                            name="privacy" 
                            checked={isPrivate} 
                            onChange={() => setIsPrivate(true)}
                            className="w-4 h-4 text-red-600 focus:ring-red-500"
                        />
                        <span className="text-sm text-gray-700">On (Private)</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer">
                         <input 
                            type="radio" 
                            name="privacy" 
                            checked={!isPrivate} 
                            onChange={() => setIsPrivate(false)}
                            className="w-4 h-4 text-red-600 focus:ring-red-500"
                        />
                        <span className="text-sm text-gray-700">Off (Public)</span>
                    </label>
                </div>
            </div>
            <MenuItem label="Blocked Users" onClick={() => setActiveSection('BLOCKED_USERS')} />
            <MenuItem label="Languages" onClick={() => setActiveSection('LANGUAGES')} rightElement={<span className="text-gray-500 text-sm mr-2">{currentLanguage}</span>} />
            <MenuItem label="Verify Account" onClick={() => setActiveSection('VERIFY')} rightElement={currentUser.isVerified ? <span className="text-blue-500 font-bold text-xs bg-blue-50 px-2 py-1 rounded-full">Verified</span> : <span className="text-gray-400 text-xs">Not Verified</span>} />
        </div>

        {/* Help and Support */}
        <SectionHeader 
            title="Help & Support" 
            icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18.364 5.636l-3.536 3.536m0 5.656l3.536 3.536M9.172 9.172L5.636 5.636m3.536 9.192l-3.536 3.536M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-5 0a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} 
        />
        <div className="flex flex-col">
            <MenuItem label="AutoBid AI Assistant" onClick={() => setActiveSection('AI_ASSISTANT')} />
            <MenuItem label="Raise Ticket" onClick={() => setActiveSection('RAISE_TICKET')} />
            <MenuItem label="View Ticket" onClick={() => setActiveSection('VIEW_TICKETS')} />
            <MenuItem label="Contact Support Team" onClick={() => setActiveSection('CONTACT_SUPPORT')} />
        </div>

        {/* Credentials & Data */}
        <SectionHeader 
            title="Credentials & Data" 
            icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>} 
        />
        <div className="flex flex-col">
            <MenuItem label="Change Password" onClick={() => setActiveSection('CHANGE_PASSWORD')} />
            <MenuItem label="Login Devices" onClick={() => setActiveSection('DEVICES')} />

            <div className="px-6 py-2 bg-gray-50/50 text-xs font-bold text-gray-500 uppercase tracking-wider mt-2 border-t border-gray-100">Download Data</div>
            <MenuItem 
                label="Download in JSON format" 
                onClick={() => triggerDownload('json')}
                rightElement={<svg className="w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>}
            />
            <MenuItem 
                label="Download in HTML format" 
                onClick={() => triggerDownload('html')}
                rightElement={<svg className="w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>}
            />
        </div>

        {/* Login Actions */}
        <SectionHeader 
            title="Login" 
            icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" /></svg>} 
        />
        <div className="flex flex-col">
            <MenuItem label="Add Account" onClick={handleAddAccount} />
            <MenuItem label="Switch Account" onClick={handleSwitchAccount} />
