  const executeDownload = () => {
    const data = generateUserData();
    let content = '';
    let mimeType = '';
    let extension = '';

    if (downloadFormat === 'json') {
      content = JSON.stringify(data, null, 2);
      mimeType = 'application/json';
      extension = 'json';
    } else {
      // Simple HTML render of the complex object
      content = `
        <html>
