export default App;

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { Settings } from './components/Settings';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle, User } from './types';
import { MOCK_VEHICLES, CURRENT_USER, MOCK_USERS, TRANSLATIONS } from './constants';

type ViewState = 'home' | 'detail' | 'profile' | 'auth' | 'sell' | 'settings';
type AuctionFilter = 'all' | 'live' | 'upcoming';
type ProfileTab = 'auctions' | 'watchlist' | 'won' | 'lost';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // User State
  const [currentUser, setCurrentUser] = useState<User>(CURRENT_USER);
  const [currentLanguage, setCurrentLanguage] = useState('English (US)');

  // Profile State
  const [profileUser, setProfileUser] = useState<User>(CURRENT_USER); // User currently being viewed
  const [profileTab, setProfileTab] = useState<ProfileTab>('auctions');

  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Translations
  const t = TRANSLATIONS[currentLanguage] || TRANSLATIONS['English (US)'];

  // Initial load simulation
  useEffect(() => {
    // If we were real, we'd check session here.
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = (userData?: { username: string }) => {
      setIsAuthenticated(true);
      if (userData?.username) {
          const newUser: User = {
              ...CURRENT_USER,
              id: `user-${Date.now()}`,
              username: userData.username,
              fullName: userData.username, // Default fallback
              avatarUrl: `https://i.pravatar.cc/150?u=${userData.username}`,
              isVerified: false,
              followers: 0,
              following: 0,
              bio: 'New member at AutoBid.'
          };
          setCurrentUser(newUser);
          setProfileUser(newUser);
      }
      setCurrentView('home');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setCurrentUser(CURRENT_USER); // Reset to default/mock
      setProfileUser(CURRENT_USER);
      setCurrentView('home');
  };

  const navigate = (view: string) => {
    if (view === 'profile') {
        // Default to current user when clicking "Profile" in nav
        setProfileUser(currentUser);
    }
    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { 
          ...v, 
          currentBid: amount,
          userBidStatus: 'winning' // Optimistically update status
      } : v
    );
    setVehicles(updatedVehicles);

    setSelectedVehicle({ ...selectedVehicle, currentBid: amount, userBidStatus: 'winning' });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  const handleListVehicle = (newVehicle: Vehicle) => {
      // Add new vehicle with ownerId of current user
      const vehicleWithOwner = { ...newVehicle, ownerId: currentUser.id };
      setVehicles(prev => [vehicleWithOwner, ...prev]);
  };

  const handleUserSearch = (user: User) => {
      setProfileUser(user);
      setProfileTab('auctions'); // Reset tab to default when viewing a new user
      navigate('profile');
  };

  // Determine font class based on language
  const getFontClass = (lang: string) => {
    switch(lang) {
      case 'Hindi': return 'font-hindi';
      case 'Marathi': return 'font-marathi';
      case 'Sanskrit': return 'font-sanskrit';
      case 'Arabic': return 'font-arabic';
      case 'Urdu': return 'font-urdu';
      case 'Telugu': return 'font-telugu';
      case 'Malayalam': return 'font-malayalam';
      case 'Tamil': return 'font-tamil';
      case 'Gujarati': return 'font-gujarati';
      case 'Punjabi': return 'font-punjabi';
      case 'Odia': return 'font-odia';
      case 'Kannada': return 'font-kannada';
      case '日本語': return 'font-jp';
      default: return 'font-outfit';
    }
  };

  const isRTL = ['Arabic', 'Urdu'].includes(currentLanguage);

  // Filter Logic for Home View
  const filteredVehicles = vehicles.filter(v => {
    // Hide sold vehicles from main feed
    if (v.status === 'Sold' || v.status === 'Sold' as any) return false; 

    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    const now = Date.now();
    const liveDurationMinutes = v.liveBidDuration || 180;
    const liveWindowMs = liveDurationMinutes * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        return timeLeft > 0 && timeLeft <= liveWindowMs;
    }
    if (auctionFilter === 'upcoming') {
        return timeLeft > liveWindowMs;
    }

    return timeLeft > 0;
  });

  // Profile Data Filtering
  const isViewingSelf = profileUser.id === currentUser.id;

  const profileListings = vehicles.filter(v => v.ownerId === profileUser.id || (isViewingSelf && v.isOwner));
  const profileWatchlist = isViewingSelf ? vehicles.filter(v => v.isWatchlisted) : [];
  const profileWon = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'won') : [];
  const profileLost = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'lost') : [];

  // Determine which tab to show vehicles for
  let activeProfileVehicles: Vehicle[] = [];
  if (profileTab === 'auctions') activeProfileVehicles = profileListings;
  else if (profileTab === 'watchlist') activeProfileVehicles = profileWatchlist;
  else if (profileTab === 'won') activeProfileVehicles = profileWon;
  else if (profileTab === 'lost') activeProfileVehicles = profileLost;


  // Force Authentication
  if (!isAuthenticated) {
      return (
          <div className={`min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
              <Auth initialMode="login" onLoginSuccess={handleLoginSuccess} t={t} />
          </div>
      );
  }

  return (
    <div className={`min-h-screen font-sans text-gray-900 pb-28 md:pb-32 bg-transparent selection:bg-red-200 selection:text-red-900 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <Navbar 
        onNavigate={navigate} 
        activePage={currentView} 
        onSearchUser={handleUserSearch} 
        currentUser={currentUser} 
        currentLanguage={currentLanguage}
      />

      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder={t.searchPlaceholder}
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setAuctionFilter('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'all' ? 'bg-gradient-to-r from-gray-800 to-gray-700 text-white shadow-gray-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-gray-900'}`}
                >
                  {t.allAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('live')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'live' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  <span className={`inline-block w-2 h-2 rounded-full mr-2 ${auctionFilter === 'live' ? 'bg-white animate-pulse' : 'bg-red-500'}`}></span>
                  {t.liveAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('upcoming')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'upcoming' ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-blue-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-blue-500'}`}
                >
                  {t.upcoming}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">
                   {auctionFilter === 'all' && t.homeTitle}
                   {auctionFilter === 'live' && t.liveAuctions}
                   {auctionFilter === 'upcoming' && t.upcoming}
                   <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span>
               </h2>
               <div className="hidden sm:block text-sm text-gray-600 bg-white/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/40">Sort by: <span className="font-bold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {isLoading ? (
               <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                 {[...Array(12)].map((_, i) => <VehicleCardSkeleton key={i} />)}
               </div>
            ) : filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                    t={t}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 glass-panel rounded-[2rem]">
