import React, { useEffect, useState } from 'react';
import { Vehicle, VehicleStatus } from '../types';

interface VehicleCardProps {
  vehicle: Vehicle;
  onClick: (vehicle: Vehicle) => void;
  t?: any;
}

// Fix: Cast default value of t to any to avoid type inference issues with empty object
export const VehicleCard: React.FC<VehicleCardProps> = ({ vehicle, onClick, t = {} as any }) => {
  const [timeLeft, setTimeLeft] = useState<string>('');
  const [displayStatus, setDisplayStatus] = useState<string>(vehicle.status);
  const [badgeColor, setBadgeColor] = useState<string>('bg-blue-600/90');
  const [isAnimate, setIsAnimate] = useState<boolean>(false);

  useEffect(() => {
    // Priority 1: Sold/Won/Lost
    if (vehicle.status === VehicleStatus.SOLD) {
        if (vehicle.userBidStatus === 'won') {
            setDisplayStatus(t?.won || 'WON');
            setBadgeColor('bg-green-600/90');
            setIsAnimate(false);
            setTimeLeft(t?.ended || 'Auction Ended');
            return;
        } else if (vehicle.userBidStatus === 'lost') {
            setDisplayStatus(t?.lost || 'LOST');
            setBadgeColor('bg-gray-600/90');
            setIsAnimate(false);
            setTimeLeft(t?.ended || 'Auction Ended');
            return;
        } else {
            setDisplayStatus(t?.sold || 'SOLD');
            setBadgeColor('bg-gray-800/90');
            setIsAnimate(false);
            setTimeLeft(t?.ended || 'Auction Ended');
            return;
        }
    }

    // Priority 2: Owner
    if (vehicle.isOwner) {
        setDisplayStatus(t?.myListing || 'MY LISTING');
        setBadgeColor('bg-indigo-600/90');
        // We still calculate time for owners to see their auction status
    }

    const calculateTimeLeft = () => {
      const now = Date.now();
      const difference = vehicle.endTime - now;

      const liveDurationMinutes = vehicle.liveBidDuration || 180;
      const liveWindowMs = liveDurationMinutes * 60 * 1000;

      if (difference <= 0) {
        if (!vehicle.isOwner && !vehicle.userBidStatus) { // Generic sold
             setDisplayStatus(t?.sold || 'SOLD');
             setBadgeColor('bg-gray-800/90');
             setIsAnimate(false);
        }
        return t?.ended || 'Ended';
      }

      // Time Calculation
      if (difference <= liveWindowMs) {
         if (!vehicle.isOwner) {
            setDisplayStatus(t?.liveAuctions || 'Live');
            setBadgeColor('bg-red-600/90');
            setIsAnimate(true);
         }
      } else {
         if (!vehicle.isOwner) {
            setDisplayStatus(t?.upcoming || 'Upcoming');
            setBadgeColor('bg-blue-600/90');
            setIsAnimate(false);
         }
      }

      const hours = Math.floor((difference / (1000 * 60 * 60)));
      const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((difference % (1000 * 60)) / 1000);

      const pad = (n: number) => n.toString().padStart(2, '0');

      if (hours > 24) {
          const days = Math.floor(hours / 24);
          const remainingHours = hours % 24;
          return `${days}d ${remainingHours}h`;
      }

      return `${hours}h ${pad(minutes)}m`;
    };

    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);

    setTimeLeft(calculateTimeLeft());

    return () => clearInterval(timer);
  }, [vehicle, t]);

  return (
    <div 
      className="glass-card rounded-2xl overflow-hidden flex flex-col cursor-pointer h-full transition-all duration-300 hover:-translate-y-1 hover:shadow-lg group"
      onClick={() => onClick(vehicle)}
    >
      <div className="relative h-32 w-full overflow-hidden">
        <img 
          src={`https://picsum.photos/id/${vehicle.imageSeed}/400/300`} 
          alt={`${vehicle.year} ${vehicle.make}`} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-60"></div>
        <div className="absolute top-1.5 left-1.5">
           <span className={`px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider rounded-full text-white shadow-md backdrop-blur-md border border-white/20 ${badgeColor} ${isAnimate ? 'animate-pulse' : ''}`}>
             {displayStatus}
           </span>
        </div>
        <div className="absolute bottom-1.5 right-1.5 bg-white/20 backdrop-blur-md border border-white/30 text-white text-[9px] font-medium px-1.5 py-0.5 rounded-full shadow-sm">
          {vehicle.odometer.toLocaleString()} mi
        </div>
      </div>

      <div className="p-2 flex-1 flex flex-col relative">
        <div className="absolute -top-4 right-2 bg-white rounded-lg p-1 shadow-md border border-gray-100 min-w-[3rem]">
             <div className="text-[7px] text-gray-400 font-bold uppercase text-center leading-none mb-0.5">BID</div>
             <div className="text-gray-900 font-bold text-xs leading-none text-center">₹{(vehicle.currentBid/1000).toFixed(1)}k</div>
        </div>

        <h3 className="text-sm font-bold text-gray-800 leading-tight mb-0.5 group-hover:text-red-600 transition-colors pr-12 truncate">
          {vehicle.year} {vehicle.make} {vehicle.model}
        </h3>
        <p className="text-[9px] text-gray-500 mb-2 font-medium tracking-wide">{t?.vin || 'VIN'}: {vehicle.vin}</p>

        <div className="grid grid-cols-2 gap-y-1 gap-x-1 text-[9px] mb-2 bg-white/40 rounded-lg p-1.5 border border-white/50">
          <div>
            <span className="block text-gray-400 text-[8px] uppercase font-bold">Damage</span>
            <span className="font-semibold text-gray-700 text-[9px] truncate block">{vehicle.primaryDamage}</span>
          </div>
          <div>
            <span className="block text-gray-400 text-[8px] uppercase font-bold">Retail Est.</span>
            <span className="font-semibold text-gray-700 text-[9px] block">₹{(vehicle.estRetailValue/1000).toFixed(0)}k</span>
          </div>
          <div className="col-span-2">
            <span className="block text-gray-400 text-[8px] uppercase font-bold">Location</span>
            <span className="font-semibold text-gray-700 text-[9px] truncate block">{vehicle.location}</span>
          </div>
        </div>

        <div className="mt-auto">
          <div className="flex justify-between items-center bg-gray-50/50 rounded-full px-2 py-1 border border-white/60">
            <span className="text-gray-500 text-[9px] font-medium">{vehicle.status === VehicleStatus.SOLD ? (t?.saleStatus || 'Status') : (t?.timeLeft || 'Ends in')}</span>
            <span className={`font-mono font-bold text-[10px] ${isAnimate ? 'text-red-600' : 'text-gray-700'}`}>
              {timeLeft}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Vehicle } from "../types";

// Helper to get AI instance safely
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateVehicleAnalysis = async (vehicle: Vehicle): Promise<string> => {
  try {
    const ai = getAI();
    const prompt = `
      You are an expert automotive auction analyst and mechanic. 
      Analyze the following vehicle listed for auction and provide a concise, professional assessment for a potential bidder.

      Vehicle Details:
      - ${vehicle.year} ${vehicle.make} ${vehicle.model}
      - VIN: ${vehicle.vin}
      - Odometer: ${vehicle.odometer} miles
      - Engine: ${vehicle.engine}
      - Top Speed: ${vehicle.topSpeed || 'N/A'}
      - MPG: ${vehicle.mpg || 'N/A'}
      - Primary Damage: ${vehicle.primaryDamage}
      - Secondary Damage: ${vehicle.secondaryDamage || 'None'}
      - Status: ${vehicle.status}
      - Has Keys: ${vehicle.hasKeys ? 'Yes' : 'No'}
      - Estimated Retail Value: $${vehicle.estRetailValue}
      - Current Bid: $${vehicle.currentBid}
      - Seller Description: ${vehicle.description || 'None provided'}

      Please cover:
      1. **Risk Assessment**: Given the damage type (${vehicle.primaryDamage}), what are the hidden risks?
      2. **Repair Complexity**: Estimate if this is a DIY job, body-shop only, or specialized repair.
      3. **Value Proposition**: Is the current bid vs retail value attractive considering likely repair costs?

      Keep the tone objective and warning-oriented but highlighting opportunity if present. Format with Markdown bolding for key terms.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 } // Fast response needed
      }
    });

    return response.text || "Analysis currently unavailable.";
  } catch (error) {
    console.error("Error generating vehicle analysis:", error);
    return "AI Analysis service is temporarily unavailable. Please verify the vehicle details manually.";
  }
};

export const validateCarImage = async (base64Data: string, mimeType: string): Promise<boolean> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          {
            text: "Does this image contain a vehicle (car, truck, suv, van)? Answer strictly with 'YES' or 'NO'."
          }
        ]
      }
    });

    const text = response.text?.trim().toUpperCase();
    return text?.includes('YES') ?? false;
  } catch (error) {
    console.error("Error validating car image:", error);
    return true;
  }
};

export interface VehicleImageAnalysis {
  isVehicle: boolean;
  make?: string;
  model?: string;
  year?: string;
  color?: string;
  bodyType?: string;
  engine?: string;
  topSpeed?: string;
  mpg?: string;
}

export const analyzeVehicleImage = async (base64Data: string, mimeType: string): Promise<VehicleImageAnalysis> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          {
            text: `Analyze this image. 
            1. First, determine if it contains a vehicle.
            2. If yes, identify the Make, Model, and approximate Year.
            3. Based on the identified vehicle, provide standard technical specifications for the base model of this car.

            Return the result as a raw JSON object (no markdown, no code blocks) with the following structure:
            {
              "isVehicle": boolean,
              "make": "string",
              "model": "string",
              "year": "string",
              "color": "string",
              "bodyType": "string",
              "engine": "string (e.g. 2.0L 4-Cyl)",
              "topSpeed": "string (e.g. 130 mph)",
              "mpg": "string (e.g. 25/35 mpg)"
            }`
          }
        ]
      }
    });

    const text = response.text || "";
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();

    try {
      const data = JSON.parse(cleanText) as VehicleImageAnalysis;
      return data;
    } catch (e) {
      console.warn("Failed to parse JSON from AI response, returning raw detection", text);
      const isVehicle = text.toLowerCase().includes('true') || text.toLowerCase().includes('yes');
      return { isVehicle };
    }

  } catch (error) {
    console.error("Error analyzing car image:", error);
    return { isVehicle: false };
  }
};

