                            </div>

                            {/* Stats */}
                            <div className="flex justify-around md:justify-start gap-8 md:gap-10 mb-4 border-t border-b md:border-none border-gray-100 py-3 md:py-0">
                                <div className="text-center md:text-left">
                                    <span className="font-semibold text-gray-900 block md:inline mr-1">{profileListings.length}</span>
                                    <span className="text-gray-500 text-sm">auctions</span>
                                </div>
                                <div className="text-center md:text-left">
                                    <span className="font-semibold text-gray-900 block md:inline mr-1">{profileUser.followers}</span>
                                    <span className="text-gray-500 text-sm">followers</span>
                                </div>
                                <div className="text-center md:text-left">
                                    <span className="font-semibold text-gray-900 block md:inline mr-1">{profileUser.following}</span>
                                    <span className="text-gray-500 text-sm">following</span>
                                </div>
                            </div>

                            {/* Bio (Desktop) */}
                            <div className="hidden md:block">
                                <p className="font-semibold text-gray-900 text-sm">{profileUser.fullName}</p>
                                <p className="text-gray-600 text-sm whitespace-pre-line">{profileUser.bio}</p>
                            </div>
                        </div>
                    </div>

                    {/* Bio (Mobile) */}
                    <div className="md:hidden px-2 mt-2">
                        <p className="font-semibold text-gray-900 text-sm">{profileUser.fullName}</p>
                        <p className="text-gray-600 text-sm whitespace-pre-line">{profileUser.bio}</p>
                    </div>
                </div>

                {/* Tabs - Instagram Style */}
                <div className="border-t border-gray-200">
                    <div className="flex justify-center gap-12">
                         <button 
                            onClick={() => setProfileTab('auctions')}
                            className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'auctions' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                        >
                            <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
                            Auctions
                        </button>
                        {isViewingSelf && (
                            <>
                                <button 
                                    onClick={() => setProfileTab('watchlist')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'watchlist' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                     <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                                    Saved
                                </button>
                                <button 
                                    onClick={() => setProfileTab('won')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'won' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                    Won
                                </button>
                                <button 
                                    onClick={() => setProfileTab('lost')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'lost' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                                    Lost
                                </button>
                            </>
                        )}
                    </div>
                </div>

                {/* Image Grid */}
                <div className="grid grid-cols-3 gap-1 md:gap-4 mt-1">
                     {activeProfileVehicles.map(vehicle => (
                         <div 
                            key={vehicle.id} 
                            onClick={() => handleVehicleClick(vehicle)}
                            className="relative aspect-square group cursor-pointer overflow-hidden bg-gray-200"
                        >
                            <img 
                                src={`https://picsum.photos/id/${vehicle.imageSeed}/500/500`} 
                                alt={vehicle.model}
                                className="w-full h-full object-cover"
                            />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 text-white font-bold">
                                <div className="flex flex-col items-center">
                                     <span className="text-xs uppercase font-light">Bid</span>
                                     <span>₹{(vehicle.currentBid/1000).toFixed(1)}k</span>
                                </div>
                            </div>
                            {/* Status Badge Mini */}
                            {vehicle.status === 'Live Auction' && (
                                <div className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full border border-white animate-pulse"></div>
                            )}
                         </div>
                     ))}
                     {activeProfileVehicles.length === 0 && (
                         <div className="col-span-3 py-20 text-center text-gray-500 text-sm">
                             {isViewingSelf 
                                ? "No vehicles found in this section." 
                                : "This user has no active auctions."}
                         </div>
                     )}
                </div>
            </div>
          )
        )}
      </main>

      {currentView !== 'settings' && (
        <footer className="glass-panel border-t border-white/40 mt-12 backdrop-blur-xl">
          <div className="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 md:grid-cols-4 gap-12">
            <div>
              <span className="text-2xl font-bold text-gray-900 tracking-tighter italic">Auto<span className="text-red-600">Bid</span></span>
              <p className="mt-4 text-sm text-gray-500 font-medium leading-relaxed">{t.footerAboutText}</p>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.auctions}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.todaysAuctions}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.joinAuction}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.auctionCalendar}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerServices}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.transportation}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.conditionReports}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.brokerServices}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerSupport}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.helpCenter}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.contactUs}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.locations}</a></li>
              </ul>
            </div>
          </div>
          <div className="max-w-7xl mx-auto px-6 py-8 border-t border-gray-200/50 text-xs text-gray-400 text-center font-medium">
            {t.footerRights}
          </div>
        </footer>
      )}

      <BottomNav onNavigate={navigate} activePage={currentView} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { Settings } from './components/Settings';
import { SearchUsers } from './components/SearchUsers';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle, User } from './types';
import { MOCK_VEHICLES, CURRENT_USER, MOCK_USERS, TRANSLATIONS } from './constants';

type ViewState = 'home' | 'detail' | 'profile' | 'auth' | 'sell' | 'settings' | 'search';
type AuctionFilter = 'all' | 'live' | 'upcoming';
type ProfileTab = 'auctions' | 'watchlist' | 'won' | 'lost';

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // User State
  const [currentUser, setCurrentUser] = useState<User>(CURRENT_USER);
  const [currentLanguage, setCurrentLanguage] = useState('English (US)');

  // Profile State
  const [profileUser, setProfileUser] = useState<User>(CURRENT_USER); // User currently being viewed
  const [profileTab, setProfileTab] = useState<ProfileTab>('auctions');

  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Translations
  const t = TRANSLATIONS[currentLanguage] || TRANSLATIONS['English (US)'];

  // Initial load simulation
  useEffect(() => {
    // If we were real, we'd check session here.
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = (userData?: { username: string }) => {
      setIsAuthenticated(true);
      if (userData?.username) {
          const newUser: User = {
              ...CURRENT_USER,
              id: `user-${Date.now()}`,
              username: userData.username,
              fullName: userData.username, // Default fallback
              avatarUrl: `https://i.pravatar.cc/150?u=${userData.username}`,
              isVerified: false,
              followers: 0,
              following: 0,
              bio: 'New member at AutoBid.'
          };
          setCurrentUser(newUser);
          setProfileUser(newUser);
      }
      setCurrentView('home');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setCurrentUser(CURRENT_USER); // Reset to default/mock
      setProfileUser(CURRENT_USER);
      setCurrentView('home');
  };

  const navigate = (view: string) => {
    if (view === 'profile') {
        // Default to current user when clicking "Profile" in nav
        setProfileUser(currentUser);
    }
    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { 
          ...v, 
          currentBid: amount,
          userBidStatus: 'winning' // Optimistically update status
      } : v
    );
    setVehicles(updatedVehicles);

    setSelectedVehicle({ ...selectedVehicle, currentBid: amount, userBidStatus: 'winning' });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  const handleListVehicle = (newVehicle: Vehicle) => {
      // Add new vehicle with ownerId of current user
      const vehicleWithOwner = { ...newVehicle, ownerId: currentUser.id };
      setVehicles(prev => [vehicleWithOwner, ...prev]);
  };

  const handleUserSearch = (user: User) => {
      setProfileUser(user);
      setProfileTab('auctions'); // Reset tab to default when viewing a new user
      navigate('profile');
  };

  // Determine font class based on language
  const getFontClass = (lang: string) => {
    switch(lang) {
      case 'Hindi': return 'font-hindi';
      case 'Marathi': return 'font-marathi';
      case 'Sanskrit': return 'font-sanskrit';
      case 'Arabic': return 'font-arabic';
      case 'Urdu': return 'font-urdu';
      case 'Telugu': return 'font-telugu';
      case 'Malayalam': return 'font-malayalam';
      case 'Tamil': return 'font-tamil';
      case 'Gujarati': return 'font-gujarati';
      case 'Punjabi': return 'font-punjabi';
      case 'Odia': return 'font-odia';
      case 'Kannada': return 'font-kannada';
      case '日本語': return 'font-jp';
      default: return 'font-outfit';
    }
  };

  const isRTL = ['Arabic', 'Urdu'].includes(currentLanguage);

  // Filter Logic for Home View
  const filteredVehicles = vehicles.filter(v => {
    // Hide sold vehicles from main feed
    if (v.status === 'Sold' || v.status === 'Sold' as any) return false; 

    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    const now = Date.now();
    const liveDurationMinutes = v.liveBidDuration || 180;
    const liveWindowMs = liveDurationMinutes * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        return timeLeft > 0 && timeLeft <= liveWindowMs;
    }
    if (auctionFilter === 'upcoming') {
        return timeLeft > liveWindowMs;
    }

    return timeLeft > 0;
  });

  // Profile Data Filtering
  const isViewingSelf = profileUser.id === currentUser.id;

  const profileListings = vehicles.filter(v => v.ownerId === profileUser.id || (isViewingSelf && v.isOwner));
  const profileWatchlist = isViewingSelf ? vehicles.filter(v => v.isWatchlisted) : [];
  const profileWon = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'won') : [];
  const profileLost = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'lost') : [];

  // Determine which tab to show vehicles for
  let activeProfileVehicles: Vehicle[] = [];
  if (profileTab === 'auctions') activeProfileVehicles = profileListings;
  else if (profileTab === 'watchlist') activeProfileVehicles = profileWatchlist;
  else if (profileTab === 'won') activeProfileVehicles = profileWon;
  else if (profileTab === 'lost') activeProfileVehicles = profileLost;


  // Force Authentication
  if (!isAuthenticated) {
      return (
          <div className={`min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
              <Auth initialMode="login" onLoginSuccess={handleLoginSuccess} t={t} />
          </div>
      );
  }

  return (
    <div className={`min-h-screen font-sans text-gray-900 pb-28 md:pb-32 bg-transparent selection:bg-red-200 selection:text-red-900 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <Navbar 
        onNavigate={navigate} 
        activePage={currentView} 
        currentUser={currentUser} 
        currentLanguage={currentLanguage}
      />

      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder={t.searchPlaceholder}
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setAuctionFilter('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'all' ? 'bg-gradient-to-r from-gray-800 to-gray-700 text-white shadow-gray-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-gray-900'}`}
                >
                  {t.allAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('live')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'live' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  <span className={`inline-block w-2 h-2 rounded-full mr-2 ${auctionFilter === 'live' ? 'bg-white animate-pulse' : 'bg-red-500'}`}></span>
                  {t.liveAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('upcoming')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'upcoming' ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-blue-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-blue-500'}`}
                >
                  {t.upcoming}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">
                   {auctionFilter === 'all' && t.homeTitle}
                   {auctionFilter === 'live' && t.liveAuctions}
                   {auctionFilter === 'upcoming' && t.upcoming}
                   <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span>
               </h2>
               <div className="hidden sm:block text-sm text-gray-600 bg-white/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/40">Sort by: <span className="font-bold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {isLoading ? (
               <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                 {[...Array(12)].map((_, i) => <VehicleCardSkeleton key={i} />)}
               </div>
            ) : filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                    t={t}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 glass-panel rounded-[2rem]">
                <h3 className="text-xl font-bold text-gray-900">No vehicles found</h3>
                <p className="text-gray-500 mt-2">
                    {auctionFilter === 'live' ? "No auctions are ending in the next 3 hours." : "Try adjusting your search terms or filters."}
                </p>
              </div>
            )}
          </div>
        )}

        {currentView === 'detail' && (
           isLoading ? (
             <VehicleDetailSkeleton />
           ) : (
             selectedVehicle && (
                <VehicleDetail 
                  vehicle={selectedVehicle} 
                  onBack={handleBackToHome}
                  onPlaceBid={handlePlaceBid}
                  t={t}
                />
             )
           )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'search' && (
            <SearchUsers onSearchUser={handleUserSearch} t={t} />
        )}

        {currentView === 'settings' && (
            <Settings 
                onNavigate={navigate} 
                onLogout={handleLogout} 
                currentUser={currentUser} 
                currentLanguage={currentLanguage}
                setLanguage={setCurrentLanguage}
                t={t}
            />
        )}

        {currentView === 'profile' && (
          isLoading ? (
            <div className="max-w-3xl mx-auto px-4 py-8 animate-pulse">
               <div className="flex gap-8 items-center mb-8">
                   <div className="w-32 h-32 rounded-full bg-gray-200"></div>
                   <div className="flex-1 space-y-4">
                       <div className="h-8 w-48 bg-gray-200 rounded"></div>
                       <div className="h-4 w-3/4 bg-gray-200 rounded"></div>
                   </div>
               </div>
               <div className="grid grid-cols-3 gap-1">
                   {[1,2,3,4,5,6].map(i => <div key={i} className="aspect-square bg-gray-200"></div>)}
               </div>
            </div>
          ) : (
             <div className="max-w-2xl mx-auto px-4 pt-2 pb-20">
                {/* Username Header (Mobile style) */}
                <div className="flex items-center justify-center gap-1 mb-6 relative">
                    <span className="text-lg font-bold text-gray-900">{profileUser.username}</span>
                    {profileUser.isVerified && (
                       <svg className="w-4 h-4 text-blue-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    )}
                </div>

                <div className="flex items-center justify-between mb-4">
                     {/* Avatar Column */}
                    <div className="relative">
                        {/* Note Bubble */}
                        <div className="absolute -top-10 -left-4 z-10 animate-fade-in-up">
                             <div className="bg-gray-100/90 backdrop-blur-md px-3 py-1.5 rounded-xl rounded-bl-none shadow-sm border border-gray-200">
                                <p className="text-[10px] font-medium text-gray-600">Note...</p>
                             </div>
                        </div>

                        <div className="w-20 h-20 md:w-24 md:h-24 rounded-full p-[2px] bg-gradient-to-tr from-gray-200 to-white shadow-sm">
                            <img 
                                src={profileUser.avatarUrl} 
                                alt={profileUser.username}
                                className="w-full h-full rounded-full object-cover border-2 border-white"
                            />
                        </div>
                    </div>

                    {/* Stats Row */}
                    <div className="flex-1 flex justify-around ml-4 md:ml-12">
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileListings.length}</span>
                           <span className="text-xs text-gray-900">posts</span>
                       </div>
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileUser.followers}</span>
                           <span className="text-xs text-gray-900">follower</span>
                       </div>
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileUser.following}</span>
                           <span className="text-xs text-gray-900">following</span>
                       </div>
                    </div>
                </div>

                {/* Bio Section */}
                <div className="mb-6 px-1">
                    <h1 className="font-bold text-gray-900 text-sm mb-0.5">{profileUser.fullName}</h1>
                    <div className="text-sm text-gray-900 whitespace-pre-line leading-snug">
                       {profileUser.bio}
                    </div>
                </div>

                {/* Buttons */}
                <div className="flex gap-2 mb-8">
                     {isViewingSelf ? (
                        <>
                            <button className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                Edit Profile
                            </button>
                            <button className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                View archive
                            </button>
                        </>
                     ) : (
                        <>
                            <button className="flex-1 bg-blue-500 hover:bg-blue-600 text-white font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                Follow
                            </button>
                            <button className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                Message
                            </button>
                        </>
                     )}
                     <button className="bg-gray-200 hover:bg-gray-300 text-gray-900 px-2 rounded-lg transition-colors flex items-center justify-center">
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                     </button>
                </div>

                {/* Tabs - Instagram Style */}
                <div className="border-t border-gray-200">
                    <div className="flex justify-center gap-12">
                         <button 
                            onClick={() => setProfileTab('auctions')}
                            className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'auctions' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                        >
                            <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
                            <span className="hidden md:inline">Auctions</span>
                        </button>
                        {isViewingSelf && (
                            <>
                                <button 
                                    onClick={() => setProfileTab('watchlist')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'watchlist' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                     <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                                    <span className="hidden md:inline">Saved</span>
                                </button>
                                <button 
                                    onClick={() => setProfileTab('won')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'won' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                    <span className="hidden md:inline">Won</span>
                                </button>
                                <button 
                                    onClick={() => setProfileTab('lost')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'lost' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                                    <span className="hidden md:inline">Lost</span>
                                </button>
                            </>
                        )}
                    </div>
                </div>

                {/* Image Grid */}
                <div className="grid grid-cols-3 gap-1 md:gap-4 mt-1">
                     {activeProfileVehicles.map(vehicle => (
                         <div 
                            key={vehicle.id} 
                            onClick={() => handleVehicleClick(vehicle)}
                            className="relative aspect-square group cursor-pointer overflow-hidden bg-gray-200"
                        >
                            <img 
                                src={`https://picsum.photos/id/${vehicle.imageSeed}/500/500`} 
                                alt={vehicle.model}
                                className="w-full h-full object-cover"
                            />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 text-white font-bold">
                                <div className="flex flex-col items-center">
                                     <span className="text-xs uppercase font-light">Bid</span>
                                     <span>₹{(vehicle.currentBid/1000).toFixed(1)}k</span>
                                </div>
                            </div>
                            {/* Status Badge Mini */}
                            {vehicle.status === 'Live Auction' && (
                                <div className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full border border-white animate-pulse"></div>
                            )}
                         </div>
                     ))}
                     {activeProfileVehicles.length === 0 && (
                         <div className="col-span-3 py-20 text-center text-gray-500 text-sm">
                             {isViewingSelf 
                                ? "No vehicles found in this section." 
                                : "This user has no active auctions."}
                         </div>
                     )}
                </div>
            </div>
          )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'search' && (
            <SearchUsers onSearchUser={handleUserSearch} t={t} />
        )}

        {currentView === 'settings' && (
            <Settings 
                onNavigate={navigate} 
                onLogout={handleLogout} 
                currentUser={currentUser} 
                currentLanguage={currentLanguage}
                setLanguage={setCurrentLanguage}
                t={t}
            />
        )}
      </main>

      {currentView !== 'settings' && (
        <footer className="glass-panel border-t border-white/40 mt-12 backdrop-blur-xl">
          <div className="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 md:grid-cols-4 gap-12">
            <div>
              <span className="text-2xl font-bold text-gray-900 tracking-tighter italic">Auto<span className="text-red-600">Bid</span></span>
              <p className="mt-4 text-sm text-gray-500 font-medium leading-relaxed">{t.footerAboutText}</p>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.auctions}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.todaysAuctions}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.joinAuction}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.auctionCalendar}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerServices}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.transportation}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.conditionReports}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.brokerServices}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerSupport}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.helpCenter}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.contactUs}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.locations}</a></li>
              </ul>
            </div>
          </div>
          <div className="max-w-7xl mx-auto px-6 py-8 border-t border-gray-200/50 text-xs text-gray-400 text-center font-medium">
            {t.footerRights}
          </div>
        </footer>
      )}

      <BottomNav onNavigate={navigate} activePage={currentView} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { Settings } from './components/Settings';
import { SearchUsers } from './components/SearchUsers';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle, User } from './types';
import { MOCK_VEHICLES, CURRENT_USER, MOCK_USERS, TRANSLATIONS } from './constants';

type ViewState = 'home' | 'detail' | 'profile' | 'auth' | 'sell' | 'settings' | 'search';
type AuctionFilter = 'all' | 'live' | 'upcoming';
type ProfileTab = 'auctions' | 'watchlist' | 'won' | 'lost';

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // User State
  const [currentUser, setCurrentUser] = useState<User>(CURRENT_USER);
  const [currentLanguage, setCurrentLanguage] = useState('English (US)');

  // Profile State
  const [profileUser, setProfileUser] = useState<User>(CURRENT_USER); // User currently being viewed
  const [profileTab, setProfileTab] = useState<ProfileTab>('auctions');

  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Translations
  const t = TRANSLATIONS[currentLanguage] || TRANSLATIONS['English (US)'];

  // Initial load simulation
  useEffect(() => {
    // If we were real, we'd check session here.
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = (userData?: { username: string }) => {
      setIsAuthenticated(true);
      if (userData?.username) {
          const newUser: User = {
              ...CURRENT_USER,
              id: `user-${Date.now()}`,
              username: userData.username,
              fullName: userData.username, // Default fallback
              avatarUrl: `https://i.pravatar.cc/150?u=${userData.username}`,
              isVerified: false,
              followers: 0,
              following: 0,
              bio: 'New member at AutoBid.'
          };
          setCurrentUser(newUser);
          setProfileUser(newUser);
      }
      setCurrentView('home');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setCurrentUser(CURRENT_USER); // Reset to default/mock
      setProfileUser(CURRENT_USER);
      setCurrentView('home');
  };

  const navigate = (view: string) => {
    if (view === 'profile') {
        // Default to current user when clicking "Profile" in nav
        setProfileUser(currentUser);
    }
    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { 
          ...v, 
          currentBid: amount,
          userBidStatus: 'winning' // Optimistically update status
      } : v
    );
    setVehicles(updatedVehicles);

    setSelectedVehicle({ ...selectedVehicle, currentBid: amount, userBidStatus: 'winning' });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  const handleListVehicle = (newVehicle: Vehicle) => {
      // Add new vehicle with ownerId of current user
      const vehicleWithOwner = { ...newVehicle, ownerId: currentUser.id };
      setVehicles(prev => [vehicleWithOwner, ...prev]);
  };

  const handleUserSearch = (user: User) => {
      setProfileUser(user);
      setProfileTab('auctions'); // Reset tab to default when viewing a new user
      navigate('profile');
  };

  // Determine font class based on language
  const getFontClass = (lang: string) => {
    switch(lang) {
      case 'Hindi': return 'font-hindi';
      case 'Marathi': return 'font-marathi';
      case 'Sanskrit': return 'font-sanskrit';
      case 'Arabic': return 'font-arabic';
      case 'Urdu': return 'font-urdu';
      case 'Telugu': return 'font-telugu';
      case 'Malayalam': return 'font-malayalam';
      case 'Tamil': return 'font-tamil';
      case 'Gujarati': return 'font-gujarati';
      case 'Punjabi': return 'font-punjabi';
      case 'Odia': return 'font-odia';
      case 'Kannada': return 'font-kannada';
      case '日本語': return 'font-jp';
      default: return 'font-outfit';
    }
  };

  const isRTL = ['Arabic', 'Urdu'].includes(currentLanguage);

  // Filter Logic for Home View
  const filteredVehicles = vehicles.filter(v => {
    // Hide sold vehicles from main feed
    if (v.status === 'Sold' || v.status === 'Sold' as any) return false; 

    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    const now = Date.now();
    const liveDurationMinutes = v.liveBidDuration || 180;
    const liveWindowMs = liveDurationMinutes * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        return timeLeft > 0 && timeLeft <= liveWindowMs;
    }
    if (auctionFilter === 'upcoming') {
        return timeLeft > liveWindowMs;
    }

    return timeLeft > 0;
  });

  // Profile Data Filtering
  const isViewingSelf = profileUser.id === currentUser.id;

  const profileListings = vehicles.filter(v => v.ownerId === profileUser.id || (isViewingSelf && v.isOwner));
  const profileWatchlist = isViewingSelf ? vehicles.filter(v => v.isWatchlisted) : [];
  const profileWon = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'won') : [];
  const profileLost = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'lost') : [];

  // Determine which tab to show vehicles for
  let activeProfileVehicles: Vehicle[] = [];
  if (profileTab === 'auctions') activeProfileVehicles = profileListings;
  else if (profileTab === 'watchlist') activeProfileVehicles = profileWatchlist;
  else if (profileTab === 'won') activeProfileVehicles = profileWon;
  else if (profileTab === 'lost') activeProfileVehicles = profileLost;


  // Force Authentication
  if (!isAuthenticated) {
      return (
          <div className={`min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
              <Auth initialMode="login" onLoginSuccess={handleLoginSuccess} t={t} />
          </div>
      );
  }

  return (
    <div className={`min-h-screen font-sans text-gray-900 pb-28 md:pb-32 bg-transparent selection:bg-red-200 selection:text-red-900 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <Navbar 
        onNavigate={navigate} 
        activePage={currentView} 
        currentUser={currentUser} 
        currentLanguage={currentLanguage}
      />

      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder={t.searchPlaceholder}
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setAuctionFilter('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'all' ? 'bg-gradient-to-r from-gray-800 to-gray-700 text-white shadow-gray-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-gray-900'}`}
                >
                  {t.allAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('live')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'live' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  <span className={`inline-block w-2 h-2 rounded-full mr-2 ${auctionFilter === 'live' ? 'bg-white animate-pulse' : 'bg-red-500'}`}></span>
                  {t.liveAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('upcoming')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'upcoming' ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-blue-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-blue-500'}`}
                >
                  {t.upcoming}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">
                   {auctionFilter === 'all' && t.homeTitle}
                   {auctionFilter === 'live' && t.liveAuctions}
                   {auctionFilter === 'upcoming' && t.upcoming}
                   <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span>
               </h2>
               <div className="hidden sm:block text-sm text-gray-600 bg-white/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/40">Sort by: <span className="font-bold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {isLoading ? (
               <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                 {[...Array(12)].map((_, i) => <VehicleCardSkeleton key={i} />)}
               </div>
            ) : filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                    t={t}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 glass-panel rounded-[2rem]">
                <h3 className="text-xl font-bold text-gray-900">No vehicles found</h3>
                <p className="text-gray-500 mt-2">
                    {auctionFilter === 'live' ? "No auctions are ending in the next 3 hours." : "Try adjusting your search terms or filters."}
                </p>
              </div>
            )}
          </div>
        )}

        {currentView === 'detail' && (
           isLoading ? (
             <VehicleDetailSkeleton />
           ) : (
             selectedVehicle && (
                <VehicleDetail 
                  vehicle={selectedVehicle} 
                  onBack={handleBackToHome}
                  onPlaceBid={handlePlaceBid}
                  t={t}
                />
             )
           )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'search' && (
            <SearchUsers onSearchUser={handleUserSearch} t={t} />
        )}

        {currentView === 'settings' && (
            <Settings 
                onNavigate={navigate} 
                onLogout={handleLogout} 
                currentUser={currentUser} 
                currentLanguage={currentLanguage}
                setLanguage={setCurrentLanguage}
                t={t}
            />
        )}

        {currentView === 'profile' && (
          isLoading ? (
            <div className="max-w-3xl mx-auto px-4 py-8 animate-pulse">
               <div className="flex gap-8 items-center mb-8">
                   <div className="w-32 h-32 rounded-full bg-gray-200"></div>
                   <div className="flex-1 space-y-4">
                       <div className="h-8 w-48 bg-gray-200 rounded"></div>
                       <div className="h-4 w-3/4 bg-gray-200 rounded"></div>
                   </div>
               </div>
               <div className="grid grid-cols-3 gap-1">
                   {[1,2,3,4,5,6].map(i => <div key={i} className="aspect-square bg-gray-200"></div>)}
               </div>
            </div>
          ) : (
             <div className="max-w-2xl mx-auto px-4 pt-2 pb-20">
                {/* Username Header (Mobile style) */}
                <div className="flex items-center justify-center gap-1 mb-6 relative">
                    <span className="text-lg font-bold text-gray-900">{profileUser.username}</span>
                    {profileUser.isVerified && (
                       <svg className="w-4 h-4 text-blue-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    )}
                </div>

                <div className="flex items-center justify-between mb-4">
                     {/* Avatar Column */}
                    <div className="relative">
                        {/* Note Bubble */}
                        <div className="absolute -top-10 -left-4 z-10 animate-fade-in-up">
                             <div className="bg-gray-100/90 backdrop-blur-md px-3 py-1.5 rounded-xl rounded-bl-none shadow-sm border border-gray-200">
                                <p className="text-[10px] font-medium text-gray-600">Note...</p>
                             </div>
                        </div>

                        <div className="w-20 h-20 md:w-24 md:h-24 rounded-full p-[2px] bg-gradient-to-tr from-gray-200 to-white shadow-sm">
                            <img 
                                src={profileUser.avatarUrl} 
                                alt={profileUser.username}
                                className="w-full h-full rounded-full object-cover border-2 border-white"
                            />
                        </div>
                    </div>

                    {/* Stats Row */}
                    <div className="flex-1 flex justify-around ml-4 md:ml-12">
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileListings.length}</span>
                           <span className="text-xs text-gray-900">posts</span>
                       </div>
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileUser.followers}</span>
                           <span className="text-xs text-gray-900">follower</span>
                       </div>
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileUser.following}</span>
                           <span className="text-xs text-gray-900">following</span>
                       </div>
                    </div>
                </div>

                {/* Bio Section */}
                <div className="mb-6 px-1">
                    <h1 className="font-bold text-gray-900 text-sm mb-0.5">{profileUser.fullName}</h1>
                    <div className="text-sm text-gray-900 whitespace-pre-line leading-snug">
                       {profileUser.bio}
                    </div>
                </div>

                {/* Buttons */}
                <div className="flex gap-2 mb-8">
                     {isViewingSelf ? (
                        <>
                            <button className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                Edit Profile
                            </button>
                            <button className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                View archive
                            </button>
                        </>
                     ) : (
                        <>
                            <button className="flex-1 bg-blue-500 hover:bg-blue-600 text-white font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                Follow
                            </button>
                            <button className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-900 font-semibold py-1.5 rounded-lg text-sm transition-colors">
                                Message
                            </button>
                            <button className="bg-gray-200 hover:bg-gray-300 text-gray-900 px-2 rounded-lg transition-colors flex items-center justify-center">
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                             </button>
                        </>
                     )}
                </div>

                {/* Tabs - Instagram Style */}
                <div className="border-t border-gray-200">
                    <div className="flex justify-center gap-12">
                         <button 
                            onClick={() => setProfileTab('auctions')}
                            className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'auctions' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                        >
                            <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
                            <span className="hidden md:inline">Auctions</span>
                        </button>
                        {isViewingSelf && (
                            <>
                                <button 
                                    onClick={() => setProfileTab('watchlist')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'watchlist' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                     <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                                    <span className="hidden md:inline">Saved</span>
                                </button>
                                <button 
                                    onClick={() => setProfileTab('won')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'won' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                    <span className="hidden md:inline">Won</span>
                                </button>
                                <button 
                                    onClick={() => setProfileTab('lost')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'lost' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                                    <span className="hidden md:inline">Lost</span>
                                </button>
                            </>
                        )}
                    </div>
                </div>

                {/* Image Grid */}
                <div className="grid grid-cols-3 gap-1 md:gap-4 mt-1">
                     {activeProfileVehicles.map(vehicle => (
                         <div 
                            key={vehicle.id} 
                            onClick={() => handleVehicleClick(vehicle)}
                            className="relative aspect-square group cursor-pointer overflow-hidden bg-gray-200"
                        >
                            <img 
                                src={`https://picsum.photos/id/${vehicle.imageSeed}/500/500`} 
                                alt={vehicle.model}
                                className="w-full h-full object-cover"
                            />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 text-white font-bold">
                                <div className="flex flex-col items-center">
                                     <span className="text-xs uppercase font-light">Bid</span>
                                     <span>₹{(vehicle.currentBid/1000).toFixed(1)}k</span>
                                </div>
                            </div>
                            {/* Status Badge Mini */}
                            {vehicle.status === 'Live Auction' && (
                                <div className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full border border-white animate-pulse"></div>
                            )}
                         </div>
                     ))}
                     {activeProfileVehicles.length === 0 && (
                         <div className="col-span-3 py-20 text-center text-gray-500 text-sm">
                             {isViewingSelf 
                                ? "No vehicles found in this section." 
                                : "This user has no active auctions."}
                         </div>
                     )}
                </div>
            </div>
          )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'search' && (
            <SearchUsers onSearchUser={handleUserSearch} t={t} />
        )}

        {currentView === 'settings' && (
            <Settings 
                onNavigate={navigate} 
                onLogout={handleLogout} 
                currentUser={currentUser} 
                currentLanguage={currentLanguage}
                setLanguage={setCurrentLanguage}
                t={t}
            />
        )}
      </main>

      {currentView !== 'settings' && (
        <footer className="glass-panel border-t border-white/40 mt-12 backdrop-blur-xl">
          <div className="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 md:grid-cols-4 gap-12">
            <div>
              <span className="text-2xl font-bold text-gray-900 tracking-tighter italic">Auto<span className="text-red-600">Bid</span></span>
              <p className="mt-4 text-sm text-gray-500 font-medium leading-relaxed">{t.footerAboutText}</p>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.auctions}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.todaysAuctions}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.joinAuction}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.auctionCalendar}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerServices}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.transportation}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.conditionReports}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.brokerServices}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerSupport}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.helpCenter}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.contactUs}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.locations}</a></li>
              </ul>
            </div>
          </div>
          <div className="max-w-7xl mx-auto px-6 py-8 border-t border-gray-200/50 text-xs text-gray-400 text-center font-medium">
            {t.footerRights}
          </div>
        </footer>
      )}

      <BottomNav onNavigate={navigate} activePage={currentView} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { Settings } from './components/Settings';
import { SearchUsers } from './components/SearchUsers';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle, User } from './types';
import { MOCK_VEHICLES, CURRENT_USER, MOCK_USERS, TRANSLATIONS } from './constants';

type ViewState = 'home' | 'detail' | 'profile' | 'auth' | 'sell' | 'settings' | 'search';
type AuctionFilter = 'all' | 'live' | 'upcoming';
type ProfileTab = 'auctions' | 'watchlist' | 'won' | 'lost';

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // User State
  const [currentUser, setCurrentUser] = useState<User>(CURRENT_USER);
  const [currentLanguage, setCurrentLanguage] = useState('English (US)');

  // Profile State
  const [profileUser, setProfileUser] = useState<User>(CURRENT_USER); // User currently being viewed
  const [profileTab, setProfileTab] = useState<ProfileTab>('auctions');

  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Translations
  const t = TRANSLATIONS[currentLanguage] || TRANSLATIONS['English (US)'];

  // Initial load simulation
  useEffect(() => {
    // If we were real, we'd check session here.
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = (userData?: { username: string }) => {
      setIsAuthenticated(true);
      if (userData?.username) {
          const newUser: User = {
              ...CURRENT_USER,
              id: `user-${Date.now()}`,
              username: userData.username,
              fullName: userData.username, // Default fallback
              avatarUrl: `https://i.pravatar.cc/150?u=${userData.username}`,
              isVerified: false,
              followers: 0,
              following: 0,
              bio: 'New member at AutoBid.'
          };
          setCurrentUser(newUser);
          setProfileUser(newUser);
      }
      setCurrentView('home');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setCurrentUser(CURRENT_USER); // Reset to default/mock
      setProfileUser(CURRENT_USER);
      setCurrentView('home');
  };

  const navigate = (view: string) => {
    if (view === 'profile') {
        // Default to current user when clicking "Profile" in nav
        setProfileUser(currentUser);
    }
    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { 
          ...v, 
          currentBid: amount,
          userBidStatus: 'winning' // Optimistically update status
      } : v
    );
    setVehicles(updatedVehicles);

    setSelectedVehicle({ ...selectedVehicle, currentBid: amount, userBidStatus: 'winning' });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  const handleListVehicle = (newVehicle: Vehicle) => {
      // Add new vehicle with ownerId of current user
      const vehicleWithOwner = { ...newVehicle, ownerId: currentUser.id };
      setVehicles(prev => [vehicleWithOwner, ...prev]);
  };

  const handleUserSearch = (user: User) => {
      setProfileUser(user);
      setProfileTab('auctions'); // Reset tab to default when viewing a new user
      navigate('profile');
  };

  // Determine font class based on language
  const getFontClass = (lang: string) => {
    switch(lang) {
      case 'Hindi': return 'font-hindi';
      case 'Marathi': return 'font-marathi';
      case 'Sanskrit': return 'font-sanskrit';
      case 'Arabic': return 'font-arabic';
      case 'Urdu': return 'font-urdu';
      case 'Telugu': return 'font-telugu';
      case 'Malayalam': return 'font-malayalam';
      case 'Tamil': return 'font-tamil';
      case 'Gujarati': return 'font-gujarati';
      case 'Punjabi': return 'font-punjabi';
      case 'Odia': return 'font-odia';
      case 'Kannada': return 'font-kannada';
      case '日本語': return 'font-jp';
      default: return 'font-outfit';
    }
  };

  const isRTL = ['Arabic', 'Urdu'].includes(currentLanguage);

  // Filter Logic for Home View
  const filteredVehicles = vehicles.filter(v => {
    // Hide sold vehicles from main feed
    if (v.status === 'Sold' || v.status === 'Sold' as any) return false; 

    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    const now = Date.now();
    const liveDurationMinutes = v.liveBidDuration || 180;
    const liveWindowMs = liveDurationMinutes * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        return timeLeft > 0 && timeLeft <= liveWindowMs;
    }
    if (auctionFilter === 'upcoming') {
        return timeLeft > liveWindowMs;
    }

    return timeLeft > 0;
  });

  // Profile Data Filtering
  const isViewingSelf = profileUser.id === currentUser.id;

  const profileListings = vehicles.filter(v => v.ownerId === profileUser.id || (isViewingSelf && v.isOwner));
  const profileWatchlist = isViewingSelf ? vehicles.filter(v => v.isWatchlisted) : [];
  const profileWon = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'won') : [];
  const profileLost = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'lost') : [];

  // Determine which tab to show vehicles for
  let activeProfileVehicles: Vehicle[] = [];
  if (profileTab === 'auctions') activeProfileVehicles = profileListings;
  else if (profileTab === 'watchlist') activeProfileVehicles = profileWatchlist;
  else if (profileTab === 'won') activeProfileVehicles = profileWon;
  else if (profileTab === 'lost') activeProfileVehicles = profileLost;


  // Force Authentication
  if (!isAuthenticated) {
      return (
          <div className={`min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
              <Auth initialMode="login" onLoginSuccess={handleLoginSuccess} t={t} />
          </div>
      );
  }

  return (
    <div className={`min-h-screen font-sans text-gray-900 pb-28 md:pb-32 bg-transparent selection:bg-red-200 selection:text-red-900 ${getFontClass(currentLanguage)}`} dir={isRTL ? 'rtl' : 'ltr'}>
      <Navbar 
        onNavigate={navigate} 
        activePage={currentView} 
        currentUser={currentUser} 
        currentLanguage={currentLanguage}
      />

      <main>
        {currentView === 'home' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
            <div className="glass-panel p-2 rounded-[2rem] mb-8 flex flex-col md:flex-row gap-2 items-center justify-between">
              <div className="flex-1 w-full md:w-auto p-2">
                <input 
                  type="text" 
                  placeholder={t.searchPlaceholder}
                  className="w-full bg-white/60 border border-white/50 rounded-2xl px-6 py-3 focus:ring-2 focus:ring-red-300 focus:bg-white transition-all outline-none text-gray-700 shadow-sm"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex gap-2 w-full md:w-auto overflow-x-auto p-2 scrollbar-hide">
                <button 
                  onClick={() => setAuctionFilter('all')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'all' ? 'bg-gradient-to-r from-gray-800 to-gray-700 text-white shadow-gray-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-gray-900'}`}
                >
                  {t.allAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('live')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'live' ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-red-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-red-500'}`}
                >
                  <span className={`inline-block w-2 h-2 rounded-full mr-2 ${auctionFilter === 'live' ? 'bg-white animate-pulse' : 'bg-red-500'}`}></span>
                  {t.liveAuctions}
                </button>
                <button 
                  onClick={() => setAuctionFilter('upcoming')}
                  className={`px-6 py-3 rounded-2xl text-sm font-bold transition-all shadow-sm whitespace-nowrap ${auctionFilter === 'upcoming' ? 'bg-gradient-to-r from-blue-600 to-blue-500 text-white shadow-blue-200' : 'bg-white/50 text-gray-600 hover:bg-white hover:text-blue-500'}`}
                >
                  {t.upcoming}
                </button>
              </div>
            </div>

            <div className="flex items-center justify-between mb-6 px-2">
               <h2 className="text-2xl font-bold text-gray-800 tracking-tight">
                   {auctionFilter === 'all' && t.homeTitle}
                   {auctionFilter === 'live' && t.liveAuctions}
                   {auctionFilter === 'upcoming' && t.upcoming}
                   <span className="text-gray-500 font-normal text-base ml-2 bg-white/40 px-3 py-1 rounded-full">{!isLoading && `${filteredVehicles.length} Vehicles`}</span>
               </h2>
               <div className="hidden sm:block text-sm text-gray-600 bg-white/30 backdrop-blur-md px-4 py-2 rounded-full border border-white/40">Sort by: <span className="font-bold text-gray-900 cursor-pointer">Time Ending Soonest ▼</span></div>
            </div>

            {isLoading ? (
               <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                 {[...Array(12)].map((_, i) => <VehicleCardSkeleton key={i} />)}
               </div>
            ) : filteredVehicles.length > 0 ? (
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                {filteredVehicles.map(vehicle => (
                  <VehicleCard 
                    key={vehicle.id} 
                    vehicle={vehicle} 
                    onClick={handleVehicleClick} 
                    t={t}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 glass-panel rounded-[2rem]">
                <h3 className="text-xl font-bold text-gray-900">No vehicles found</h3>
                <p className="text-gray-500 mt-2">
                    {auctionFilter === 'live' ? "No auctions are ending in the next 3 hours." : "Try adjusting your search terms or filters."}
                </p>
              </div>
            )}
          </div>
        )}

        {currentView === 'detail' && (
           isLoading ? (
             <VehicleDetailSkeleton />
           ) : (
             selectedVehicle && (
                <VehicleDetail 
                  vehicle={selectedVehicle} 
                  onBack={handleBackToHome}
                  onPlaceBid={handlePlaceBid}
                  t={t}
                />
             )
           )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'search' && (
            <SearchUsers onSearchUser={handleUserSearch} t={t} />
        )}

        {currentView === 'settings' && (
            <Settings 
                onNavigate={navigate} 
                onLogout={handleLogout} 
                currentUser={currentUser} 
                currentLanguage={currentLanguage}
                setLanguage={setCurrentLanguage}
                t={t}
            />
        )}

        {currentView === 'profile' && (
          isLoading ? (
            <div className="max-w-3xl mx-auto px-4 py-8 animate-pulse">
               <div className="flex gap-8 items-center mb-8">
                   <div className="w-32 h-32 rounded-full bg-gray-200"></div>
                   <div className="flex-1 space-y-4">
                       <div className="h-8 w-48 bg-gray-200 rounded"></div>
                       <div className="h-4 w-3/4 bg-gray-200 rounded"></div>
                   </div>
               </div>
               <div className="grid grid-cols-3 gap-1">
                   {[1,2,3,4,5,6].map(i => <div key={i} className="aspect-square bg-gray-200"></div>)}
               </div>
            </div>
          ) : (
             <div className="max-w-2xl mx-auto px-4 pt-2 pb-20">
                {/* Username Header (Mobile style) */}
                <div className="flex items-center justify-center gap-1 mb-6 relative">
                    <span className="text-lg font-bold text-gray-900">{profileUser.username}</span>
                    {profileUser.isVerified && (
                       <svg className="w-4 h-4 text-blue-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    )}
                </div>

                <div className="flex items-center justify-between mb-4">
                     {/* Avatar Column */}
                    <div className="relative">
                        {/* Note Bubble */}
                        <div className="absolute -top-10 -left-4 z-10 animate-fade-in-up">
                             <div className="bg-gray-100/90 backdrop-blur-md px-3 py-1.5 rounded-xl rounded-bl-none shadow-sm border border-gray-200">
                                <p className="text-[10px] font-medium text-gray-600">Note...</p>
                             </div>
                        </div>

                        <div className="w-20 h-20 md:w-24 md:h-24 rounded-full p-[2px] bg-gradient-to-tr from-gray-200 to-white shadow-sm">
                            <img 
                                src={profileUser.avatarUrl} 
                                alt={profileUser.username}
                                className="w-full h-full rounded-full object-cover border-2 border-white"
                            />
                        </div>
                    </div>

                    {/* Stats Row */}
                    <div className="flex-1 flex justify-around ml-4 md:ml-12">
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileListings.length}</span>
                           <span className="text-xs text-gray-900">posts</span>
                       </div>
                       <div className="flex flex-col items-center cursor-pointer">
                           <span className="font-bold text-lg text-gray-900">{profileUser.followers}</span>
                           <span className="text-xs text-gray-900">followers</span>
                       </div>
