import React, { useState } from 'react';
import { User } from '../types';
import { GoogleGenAI } from "@google/genai";

interface SettingsProps {
  onNavigate: (page: string) => void;
  onLogout: () => void;
  currentUser: User;
  currentLanguage: string;
  setLanguage: (lang: string) => void;
  t: any;
}

type SettingsSection = 
  | 'MENU' 
  | 'BLOCKED_USERS' 
  | 'LANGUAGES' 
  | 'VERIFY' 
  | 'AI_ASSISTANT' 
  | 'RAISE_TICKET' 
  | 'VIEW_TICKETS' 
  | 'CONTACT_SUPPORT' 
  | 'CHANGE_PASSWORD' 
  | 'DEVICES'
  | 'ADD_ACCOUNT'
  | 'SWITCH_ACCOUNT';

export const Settings: React.FC<SettingsProps> = ({ onNavigate, onLogout, currentUser, currentLanguage, setLanguage, t }) => {
  const [activeSection, setActiveSection] = useState<SettingsSection>('MENU');

  // -- State for Account Details --
  const [isPrivate, setIsPrivate] = useState(false);
  const [blockedUsers, setBlockedUsers] = useState([
    { id: 'b1', name: 'spam_bot_99' },
    { id: 'b2', name: 'annoying_bidder' }
  ]);
  const [isVerificationPending, setIsVerificationPending] = useState(false);
  const [showDownloadConfirm, setShowDownloadConfirm] = useState(false);

  // -- State for Tickets --
  const [tickets, setTickets] = useState([
    { id: '#1023', subject: 'Payment Issue', status: 'Resolved', date: '2023-10-12' },
    { id: '#1055', subject: 'Bid Not Registering', status: 'Open', date: '2023-11-05' }
  ]);

  // -- Helpers --
  const generateUserData = () => {
    // Mock Comprehensive Data
    return {
      personalInfo: {
        id: currentUser.id,
        username: currentUser.username,
        fullName: currentUser.fullName,
        email: "alex.racer@example.com", // Mock email
        accountCreated: "2023-01-15T14:30:00Z",
        verified: currentUser.isVerified,
      },
      security: {
        passwordChangedHistory: [
          { date: "2023-01-15T14:30:00Z", reason: "Account Creation" },
          { date: "2023-06-20T09:15:00Z", reason: "User Request" }
        ],
        usernameChangeHistory: [
          { date: "2023-05-10", oldUsername: "alex_r_99", newUsername: currentUser.username }
        ],
        blockedUsersCount: blockedUsers.length,
        blockedUsersList: blockedUsers.map(u => u.id),
      },
      activity: {
        searches: ['Toyota Supra', 'Salvage Ford Raptor', 'JDM parts', 'Tesla Model 3'],
        adPreferences: {
           personalizedAds: true,
           categories: ['Sports Cars', 'Electric Vehicles', 'Car Parts'],
           demographicTargeting: '18-35 Male'
        },
        bids: {
           totalBidsMade: 45,
           won: [
             { vehicleId: '1006', model: 'Lucid Air', bidAmount: 95000, date: '2023-11-01' }
           ],
           lost: [
             { vehicleId: '1007', model: 'Dodge Challenger', bidAmount: 42000, date: '2023-10-25' }
           ],
           active: [
             { vehicleId: '1002', model: 'Ford Raptor', currentBid: 22000 }
           ]
        }
      },
      settings: { 
        isPrivate, 
        language: currentLanguage 
      },
      exportMetaData: {
        app: "AutoBid AI",
        timestamp: new Date().toISOString(),
        note: "CONFIDENTIAL - DO NOT SHARE WITH UNAUTHORIZED PARTIES"
      }
    };
  };

  const executeDownload = (format: 'json' | 'html') => {
    const data = generateUserData();
    let content = '';
    let mimeType = '';
    let extension = '';

    if (format === 'json') {
      content = JSON.stringify(data, null, 2);
      mimeType = 'application/json';
      extension = 'json';
    } else {
      // Simple HTML render of the complex object
      content = `
        <html>
          <head>
            <title>AutoBid Data Export</title>
            <style>body{font-family:sans-serif;padding:2rem;max-width:800px;margin:0 auto;line-height:1.6} .warning{color:red;font-weight:bold;border:1px solid red;padding:10px;margin-bottom:20px;}</style>
          </head>
          <body>
            <div class="warning">CONFIDENTIAL: DO NOT SHARE THIS DATA WITH UNAUTHORIZED THIRD PARTIES.</div>
            <h1>Data Export for ${currentUser.username}</h1>
            <p><strong>Export Date:</strong> ${new Date().toLocaleDateString()}</p>
            <hr/>
            <pre>${JSON.stringify(data, null, 2)}</pre>
          </body>
        </html>
      `;
      mimeType = 'text/html';
      extension = 'html';
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `autobid_${currentUser.username}_full_data.${extension}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    setShowDownloadConfirm(false);
  };

