            </div>
         ) : isVerificationPending ? (
            <div className="bg-yellow-100 text-yellow-700 px-4 py-2 rounded-xl font-bold">
              Verification Pending Review
            </div>
         ) : (
            <button 
              onClick={() => setIsVerificationPending(true)}
              className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/30"
            >
              Request Verification
            </button>
         )}
      </div>
    </div>
  );

  const AIAssistantView = () => {
    const [messages, setMessages] = useState<{role: 'user'|'model', text: string}[]>([
      { role: 'model', text: "Hi! I'm the AutoBid Assistant. How can I help you today?" }
    ]);
    const [input, setInput] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSend = async () => {
      if(!input.trim()) return;
      const userMsg = input;
      setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
      setInput('');
      setLoading(true);

      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            { role: 'user', parts: [{ text: `You are a helpful customer support agent for AutoBid, a car auction app. Answer briefly and politely. User: ${userMsg}` }] }
          ]
        });
        setMessages(prev => [...prev, { role: 'model', text: response.text || "I'm having trouble connecting right now." }]);
      } catch (e) {
        setMessages(prev => [...prev, { role: 'model', text: "Sorry, I'm offline at the moment." }]);
      } finally {
        setLoading(false);
      }
    };

    return (
      <div className="animate-fade-in-right h-[calc(100vh-140px)] flex flex-col">
        <SubViewHeader title={t.aiAssistant} />
        <div className="glass-panel flex-1 rounded-2xl overflow-hidden flex flex-col">
           <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] px-4 py-2.5 rounded-2xl text-sm ${m.role === 'user' ? 'bg-red-500 text-white rounded-br-none' : 'bg-white text-gray-800 rounded-bl-none shadow-sm'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {loading && (
                 <div className="flex justify-start">
                   <div className="bg-white px-4 py-3 rounded-2xl rounded-bl-none shadow-sm flex gap-1">
                      <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></div>
                      <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></div>
                   </div>
                 </div>
              )}
           </div>
           <div className="p-3 bg-white/50 border-t border-gray-100 flex gap-2">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask for help..."
                className="flex-1 px-4 py-2 rounded-full bg-white border border-gray-200 text-sm focus:outline-none focus:border-red-400"
              />
              <button onClick={handleSend} className="bg-red-500 text-white p-2 rounded-full">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
              </button>
           </div>
        </div>
      </div>
    );
  };

  const RaiseTicketView = () => {
    const [subject, setSubject] = useState('');
