                                Message
                            </button>
                            <button className="bg-gray-200 hover:bg-gray-300 text-gray-900 px-3 rounded-lg transition-colors flex items-center justify-center">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z"></path></svg>
                             </button>
                        </>
                     )}
                </div>

                {/* Tabs - Instagram Style */}
                <div className="border-t border-gray-200">
                    <div className="flex justify-center gap-12">
                         <button 
                            onClick={() => setProfileTab('auctions')}
                            className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'auctions' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                        >
                            <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
                            <span className="hidden md:inline">Auctions</span>
                        </button>
                        {isViewingSelf && (
                            <>
                                <button 
                                    onClick={() => setProfileTab('watchlist')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'watchlist' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                     <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                                    <span className="hidden md:inline">Saved</span>
                                </button>
                                <button 
                                    onClick={() => setProfileTab('won')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'won' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                    <span className="hidden md:inline">Won</span>
                                </button>
                                <button 
                                    onClick={() => setProfileTab('lost')}
                                    className={`flex items-center gap-2 py-3 border-t border-transparent -mt-px text-xs font-semibold tracking-widest uppercase transition-all ${profileTab === 'lost' ? 'border-gray-900 text-gray-900' : 'text-gray-400'}`}
                                >
                                    <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                                    <span className="hidden md:inline">Lost</span>
                                </button>
                            </>
                        )}
                    </div>
                </div>

                {/* Image Grid */}
                <div className="grid grid-cols-3 gap-1 md:gap-4 mt-1">
                     {activeProfileVehicles.map(vehicle => (
                         <div 
                            key={vehicle.id} 
                            onClick={() => handleVehicleClick(vehicle)}
                            className="relative aspect-square group cursor-pointer overflow-hidden bg-gray-200"
                        >
                            <img 
                                src={`https://picsum.photos/id/${vehicle.imageSeed}/500/500`} 
                                alt={vehicle.model}
                                className="w-full h-full object-cover"
                            />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 text-white font-bold">
                                <div className="flex flex-col items-center">
                                     <span className="text-xs uppercase font-light">Bid</span>
                                     <span>₹{(vehicle.currentBid/1000).toFixed(1)}k</span>
                                </div>
                            </div>
                            {/* Status Badge Mini */}
                            {vehicle.status === 'Live Auction' && (
                                <div className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full border border-white animate-pulse"></div>
                            )}
                         </div>
                     ))}
                     {activeProfileVehicles.length === 0 && (
                         <div className="col-span-3 py-20 text-center text-gray-500 text-sm">
                             {isViewingSelf 
                                ? "No vehicles found in this section." 
                                : "This user has no active auctions."}
                         </div>
                     )}
                </div>
            </div>
          )
        )}

        {currentView === 'sell' && (
            <SellCar onNavigate={navigate} onListVehicle={handleListVehicle} />
        )}

        {currentView === 'search' && (
            <SearchUsers onSearchUser={handleUserSearch} t={t} />
        )}

        {currentView === 'settings' && (
            <Settings 
                onNavigate={navigate} 
                onLogout={handleLogout} 
                currentUser={currentUser} 
                currentLanguage={currentLanguage}
                setLanguage={setCurrentLanguage}
                t={t}
            />
        )}
      </main>

      {currentView !== 'settings' && (
        <footer className="glass-panel border-t border-white/40 mt-12 backdrop-blur-xl">
          <div className="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 md:grid-cols-4 gap-12">
            <div>
              <span className="text-2xl font-bold text-gray-900 tracking-tighter italic">Auto<span className="text-red-600">Bid</span></span>
              <p className="mt-4 text-sm text-gray-500 font-medium leading-relaxed">{t.footerAboutText}</p>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.auctions}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.todaysAuctions}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.joinAuction}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.auctionCalendar}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerServices}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.transportation}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.conditionReports}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.brokerServices}</a></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-wider">{t.footerSupport}</h4>
              <ul className="space-y-3 text-sm text-gray-600 font-medium">
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.helpCenter}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.contactUs}</a></li>
                <li><a href="#" className="hover:text-red-600 transition-colors">{t.locations}</a></li>
              </ul>
            </div>
          </div>
          <div className="max-w-7xl mx-auto px-6 py-8 border-t border-gray-200/50 text-xs text-gray-400 text-center font-medium">
            {t.footerRights}
          </div>
        </footer>
      )}

      <BottomNav onNavigate={navigate} activePage={currentView} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { VehicleCard } from './components/VehicleCard';
import { VehicleDetail } from './components/VehicleDetail';
import { BottomNav } from './components/BottomNav';
import { Auth } from './components/Auth';
import { SellCar } from './components/SellCar';
import { Settings } from './components/Settings';
import { SearchUsers } from './components/SearchUsers';
import { VehicleCardSkeleton, VehicleDetailSkeleton, DashboardSkeleton } from './components/Skeletons';
import { Vehicle, User } from './types';
import { MOCK_VEHICLES, CURRENT_USER, MOCK_USERS, TRANSLATIONS } from './constants';

type ViewState = 'home' | 'detail' | 'profile' | 'auth' | 'sell' | 'settings' | 'search';
type AuctionFilter = 'all' | 'live' | 'upcoming';
type ProfileTab = 'auctions' | 'watchlist' | 'won' | 'lost';

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('home');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [vehicles, setVehicles] = useState<Vehicle[]>(MOCK_VEHICLES);
  const [searchQuery, setSearchQuery] = useState('');

  // User State
  const [currentUser, setCurrentUser] = useState<User>(CURRENT_USER);
  const [currentLanguage, setCurrentLanguage] = useState('English (US)');

  // Profile State
  const [profileUser, setProfileUser] = useState<User>(CURRENT_USER); // User currently being viewed
  const [profileTab, setProfileTab] = useState<ProfileTab>('auctions');

  const [auctionFilter, setAuctionFilter] = useState<AuctionFilter>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Translations
  const t = TRANSLATIONS[currentLanguage] || TRANSLATIONS['English (US)'];

  // Initial load simulation
  useEffect(() => {
    // If we were real, we'd check session here.
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1200);
    return () => clearTimeout(timer);
  }, []);

  const handleLoginSuccess = (userData?: { username: string }) => {
      setIsAuthenticated(true);
      if (userData?.username) {
          const newUser: User = {
              ...CURRENT_USER,
              id: `user-${Date.now()}`,
              username: userData.username,
              fullName: userData.username, // Default fallback
              avatarUrl: `https://i.pravatar.cc/150?u=${userData.username}`,
              isVerified: false,
              followers: 0,
              following: 0,
              bio: 'New member at AutoBid.'
          };
          setCurrentUser(newUser);
          setProfileUser(newUser);
      }
      setCurrentView('home');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setCurrentUser(CURRENT_USER); // Reset to default/mock
      setProfileUser(CURRENT_USER);
      setCurrentView('home');
  };

  const navigate = (view: string) => {
    if (view === 'profile') {
        // Default to current user when clicking "Profile" in nav
        setProfileUser(currentUser);
    }
    handleViewChange(view as ViewState);
  };

  const handleViewChange = (view: ViewState) => {
    setIsLoading(true);
    setCurrentView(view);
    window.scrollTo(0, 0);

    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  }

  const handleVehicleClick = (vehicle: Vehicle) => {
    setSelectedVehicle(vehicle);
    navigate('detail');
  };

  const handleBackToHome = () => {
    setSelectedVehicle(null);
    navigate('home');
  };

  const handlePlaceBid = (amount: number) => {
    if (!selectedVehicle) return;

    const updatedVehicles = vehicles.map(v => 
      v.id === selectedVehicle.id ? { 
          ...v, 
          currentBid: amount,
          userBidStatus: 'winning' as const // Optimistically update status
      } : v
    );
    setVehicles(updatedVehicles);

    setSelectedVehicle({ ...selectedVehicle, currentBid: amount, userBidStatus: 'winning' });

    alert(`Bid of ₹${amount.toLocaleString()} placed successfully!`);
  };

  const handleListVehicle = (newVehicle: Vehicle) => {
      // Add new vehicle with ownerId of current user
      const vehicleWithOwner = { ...newVehicle, ownerId: currentUser.id };
      setVehicles(prev => [vehicleWithOwner, ...prev]);
  };

  const handleUserSearch = (user: User) => {
      setProfileUser(user);
      setProfileTab('auctions'); // Reset tab to default when viewing a new user
      navigate('profile');
  };

  // Determine font class based on language
  const getFontClass = (lang: string) => {
    switch(lang) {
      case 'Hindi': return 'font-hindi';
      case 'Marathi': return 'font-marathi';
      case 'Sanskrit': return 'font-sanskrit';
      case 'Arabic': return 'font-arabic';
      case 'Urdu': return 'font-urdu';
      case 'Telugu': return 'font-telugu';
      case 'Malayalam': return 'font-malayalam';
      case 'Tamil': return 'font-tamil';
      case 'Gujarati': return 'font-gujarati';
      case 'Punjabi': return 'font-punjabi';
      case 'Odia': return 'font-odia';
      case 'Kannada': return 'font-kannada';
      case '日本語': return 'font-jp';
      default: return 'font-outfit';
    }
  };

  const isRTL = ['Arabic', 'Urdu'].includes(currentLanguage);

  // Filter Logic for Home View
  const filteredVehicles = vehicles.filter(v => {
    // Hide sold vehicles from main feed
    if (v.status === 'Sold' || v.status === 'Sold' as any) return false; 

    const matchesSearch = 
      v.make.toLowerCase().includes(searchQuery.toLowerCase()) || 
      v.model.toLowerCase().includes(searchQuery.toLowerCase()) ||
      v.vin.toLowerCase().includes(searchQuery.toLowerCase());

    if (!matchesSearch) return false;

    const now = Date.now();
    const liveDurationMinutes = v.liveBidDuration || 180;
    const liveWindowMs = liveDurationMinutes * 60 * 1000;
    const timeLeft = v.endTime - now;

    if (auctionFilter === 'live') {
        return timeLeft > 0 && timeLeft <= liveWindowMs;
    }
    if (auctionFilter === 'upcoming') {
        return timeLeft > liveWindowMs;
    }

    return timeLeft > 0;
  });

  // Profile Data Filtering
  const isViewingSelf = profileUser.id === currentUser.id;

  const profileListings = vehicles.filter(v => v.ownerId === profileUser.id || (isViewingSelf && v.isOwner));
  const profileWatchlist = isViewingSelf ? vehicles.filter(v => v.isWatchlisted) : [];
  const profileWon = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'won') : [];
  const profileLost = isViewingSelf ? vehicles.filter(v => v.userBidStatus === 'lost') : [];

  // Determine which tab to show vehicles for
