                            onClick={() => setStep(5)}
                            className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 hover:scale-105 transition-all"
                        >
                            Next Step
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* STEP 5: Auction Schedule */}
        {step === 5 && (
            <div className="mt-6 animate-fade-in-right">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Auction Schedule</h2>
                <p className="text-gray-500 mb-8">Step 5 of 5: When should your auction go live?</p>

                <form onSubmit={handleSubmit} className="space-y-8">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div 
                           onClick={() => setFormData({...formData, scheduleType: 'auto'})}
                           className={`p-6 rounded-2xl border-2 cursor-pointer transition-all ${formData.scheduleType === 'auto' ? 'border-red-500 bg-red-50/50' : 'border-gray-200 hover:border-gray-300'}`}
                        >
                           <div className="flex items-center gap-3 mb-2">
                             <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${formData.scheduleType === 'auto' ? 'border-red-500' : 'border-gray-300'}`}>
                                {formData.scheduleType === 'auto' && <div className="w-3 h-3 rounded-full bg-red-500"></div>}
                             </div>
                             <span className="font-bold text-lg text-gray-900">AutoBid Recommended</span>
                           </div>
                           <p className="text-gray-500 text-sm ml-9">Let our AI optimize the start time for maximum visibility (usually within 24 hours).</p>
                        </div>

                        <div 
                           onClick={() => setFormData({...formData, scheduleType: 'manual'})}
                           className={`p-6 rounded-2xl border-2 cursor-pointer transition-all ${formData.scheduleType === 'manual' ? 'border-red-500 bg-red-50/50' : 'border-gray-200 hover:border-gray-300'}`}
                        >
                           <div className="flex items-center gap-3 mb-2">
                             <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${formData.scheduleType === 'manual' ? 'border-red-500' : 'border-gray-300'}`}>
                                {formData.scheduleType === 'manual' && <div className="w-3 h-3 rounded-full bg-red-500"></div>}
                             </div>
                             <span className="font-bold text-lg text-gray-900">Manual Schedule</span>
                           </div>
                           <p className="text-gray-500 text-sm ml-9">You choose the exact start and end time for your auction.</p>
                        </div>
                    </div>

                    {formData.scheduleType === 'manual' && (
                        <div className="bg-white/40 p-6 rounded-2xl border border-white/60 animate-fade-in-down">

                             {/* Start Period */}
                             <div className="mb-6">
                                <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Auction Start Period</label>
                                <div className="flex flex-col sm:flex-row gap-4 p-4 bg-white/50 rounded-xl border border-gray-100">
                                    <div className="flex-1">
                                        <label className="text-xs text-gray-500 font-bold uppercase mb-1 block">Date</label>
                                        <div className="relative">
                                            <input 
                                                type="date" 
                                                name="auctionDate"
                                                value={formData.auctionDate}
                                                onChange={handleInputChange}
                                                min={today}
                                                onClick={(e) => e.currentTarget.showPicker?.()}
                                                className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-200 outline-none cursor-pointer"
                                                required
                                            />
                                        </div>
                                    </div>
                                    <div className="flex-1">
                                        <label className="text-xs text-gray-500 font-bold uppercase mb-1 block">Time</label>
                                        <div className="relative">
                                            <select 
                                                name="auctionStartTime"
                                                value={formData.auctionStartTime}
                                                onChange={handleInputChange}
                                                className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-200 outline-none appearance-none cursor-pointer"
                                                required
                                            >
                                                <option value="" disabled>Select Time</option>
                                                {timeSlots.map(slot => (
                                                    <option key={slot.value} value={slot.value}>{slot.label}</option>
                                                ))}
                                            </select>
                                            <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none text-gray-500">
                                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                             </div>

                             {/* End Period */}
                             <div className="mb-6">
                                <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Auction End Period</label>
                                <div className="flex flex-col sm:flex-row gap-4 p-4 bg-white/50 rounded-xl border border-gray-100">
                                    <div className="flex-1">
                                        <label className="text-xs text-gray-500 font-bold uppercase mb-1 block">Date</label>
                                        <div className="relative">
                                            <input 
                                                type="date" 
                                                name="auctionEndDate"
                                                value={formData.auctionEndDate}
                                                onChange={handleInputChange}
                                                min={formData.auctionDate || today}
                                                onClick={(e) => e.currentTarget.showPicker?.()}
                                                className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-200 outline-none cursor-pointer"
                                                required
                                            />
                                        </div>
                                    </div>
                                    <div className="flex-1">
                                        <label className="text-xs text-gray-500 font-bold uppercase mb-1 block">Time</label>
                                        <div className="relative">
                                            <select 
                                                name="auctionEndTime"
                                                value={formData.auctionEndTime}
                                                onChange={handleInputChange}
                                                className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-200 outline-none appearance-none cursor-pointer"
                                                required
                                            >
                                                <option value="" disabled>Select Time</option>
                                                {timeSlots.map(slot => (
                                                    <option key={slot.value} value={slot.value}>{slot.label}</option>
                                                ))}
                                            </select>
                                            <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none text-gray-500">
                                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                             </div>

                             {/* Live Bid Duration Selector */}
                             <div className="mb-6">
                                <label className="block text-sm font-bold text-gray-700 mb-2 ml-1">Live Bidding Duration</label>
                                <p className="text-xs text-gray-500 mb-2 ml-1">Select how long the "Live Auction" period should last before the auction ends.</p>
                                <div className="relative">
                                    <select 
                                        name="liveBidDuration"
                                        value={formData.liveBidDuration}
                                        onChange={handleInputChange}
                                        className="w-full px-5 py-3 bg-white/50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-red-200 focus:border-red-400 outline-none appearance-none cursor-pointer transition-all"
                                        required
                                    >
                                        <option value="10">10 Minutes</option>
                                        <option value="30">30 Minutes</option>
                                        <option value="60">60 Minutes (1 Hr)</option>
                                        <option value="90">1 Hour 30 Minutes</option>
                                        <option value="120">2 Hours</option>
                                        <option value="165">2 Hours 45 Minutes</option>
                                        <option value="180">3 Hours</option>
                                    </select>
                                    <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none text-gray-500">
                                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                                    </div>
                                </div>
                             </div>

                             {/* Schedule Summary Timeline */}
                             {formData.auctionDate && formData.auctionStartTime && formData.auctionEndDate && formData.auctionEndTime && (
                                <div className="bg-gradient-to-br from-gray-50 to-white rounded-xl p-6 border border-gray-200 shadow-sm space-y-4">
                                     <h4 className="font-bold text-gray-800 uppercase text-xs tracking-wider border-b border-gray-200 pb-2">Auction Timeline</h4>

                                     <div className="flex gap-4">
                                         <div className="flex flex-col items-center">
                                             <div className="w-3 h-3 bg-gray-400 rounded-full"></div>
                                             <div className="w-0.5 h-full bg-gray-200"></div>
                                         </div>
                                         <div className="pb-4">
                                             <p className="text-xs font-bold text-gray-500 uppercase">Listing Starts</p>
                                             <p className="text-sm font-medium text-gray-900">
                                                 {new Date(`${formData.auctionDate}T${formData.auctionStartTime}`).toLocaleString([], {dateStyle: 'short', timeStyle: 'short'})}
                                             </p>
                                         </div>
                                     </div>

                                     <div className="flex gap-4">
                                         <div className="flex flex-col items-center">
                                             <div className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></div>
                                             <div className="w-0.5 h-full bg-gray-200"></div>
                                         </div>
                                         <div className="pb-4">
                                             <p className="text-xs font-bold text-red-500 uppercase">Live Bidding Starts</p>
                                             <p className="text-sm font-medium text-gray-900">
                                                 {getLiveBidStartTime()?.toLocaleString([], {dateStyle: 'short', timeStyle: 'short'}) || '...'}
                                             </p>
                                             <p className="text-xs text-gray-400 mt-1">({formData.liveBidDuration} minutes before end)</p>
                                         </div>
                                     </div>

                                     <div className="flex gap-4">
                                         <div className="flex flex-col items-center">
                                             <div className="w-3 h-3 bg-gray-900 rounded-full"></div>
                                         </div>
                                         <div>
                                             <p className="text-xs font-bold text-gray-900 uppercase">Auction Ends</p>
                                             <p className="text-sm font-medium text-gray-900">
                                                 {new Date(`${formData.auctionEndDate}T${formData.auctionEndTime}`).toLocaleString([], {dateStyle: 'short', timeStyle: 'short'})}
                                             </p>
                                         </div>
                                     </div>
                                </div>
                             )}

                             {/* Duration Preview */}
                             <div className="bg-gradient-to-r from-red-50 to-white rounded-xl p-5 flex flex-col sm:flex-row items-center justify-between border border-red-100 shadow-sm mt-4">
                                 <span className="text-gray-500 text-sm font-bold uppercase tracking-wider mb-1 sm:mb-0">Total Listing Duration</span>
                                 <span className="text-gray-900 font-bold text-lg">
                                    {getDurationDisplay()}
                                 </span>
                             </div>
                        </div>
                    )}

                    <div className="flex justify-between mt-8 pt-4 border-t border-gray-200/50">
                        <button 
                            type="button"
                            onClick={() => setStep(4)}
                            className="text-gray-500 font-bold px-6 py-3 hover:text-gray-700 transition-colors"
                        >
                            Back
                        </button>
                        <button 
                            type="submit"
                            className="bg-gradient-to-r from-red-600 to-orange-500 text-white font-bold px-8 py-3 rounded-xl shadow-lg shadow-red-500/30 hover:scale-105 transition-all"
                        >
                            List Vehicle
                        </button>
                    </div>
                </form>
            </div>
        )}

        {/* STEP 6: Success */}
        {step === 6 && (
            <div className="mt-6 text-center animate-fade-in-up py-12">
                <div className="w-24 h-24 bg-green-100 text-green-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-green-100 shadow-xl">
                    <svg className="w-12 h-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                </div>
                <h2 className="text-4xl font-bold text-gray-900 mb-4">Listing Successful!</h2>
                <p className="text-gray-500 text-lg mb-8 max-w-md mx-auto">Your vehicle has been submitted for auction review. You can track its status in your dashboard.</p>

                <button 
                    onClick={() => onNavigate('dashboard')}
                    className="bg-gray-900 text-white font-bold px-8 py-4 rounded-xl shadow-lg hover:scale-105 transition-all"
                >
                    Go to Dashboard
                </button>
            </div>
        )}
      </div>
    </div>
  );
};
